/* مُولَّد آليًا من نموذج البيانات (tools/dbgen) — لا يُعدَّل يدويًا؛ عدِّل النموذج وأعد التوليد. */
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET ARITHABORT ON; SET CONCAT_NULL_YIELDS_NULL ON; SET NUMERIC_ROUNDABORT OFF;  -- مطلوبة للفهارس المصفّاة والأعمدة المحسوبة المخزَّنة (sqlcmd يفترض QUOTED_IDENTIFIER OFF)
GO
-- ===== schema plat =====
-- Subscription plan: a bundle of modules and soft limits (FR-PLT-003/004, Q-PLT-11)
CREATE TABLE [plat].[Plan] (
    [PlanId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(30) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [MaxUsers] INT NULL,
    [MaxCompanies] INT NULL,
    [MaxStorageGb] INT NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Plan_IsActive] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Plan_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_Plan] PRIMARY KEY CLUSTERED ([PlanId]),
    CONSTRAINT [UQ_Plan_Code] UNIQUE ([Code]),
    CONSTRAINT [CK_Plan_1] CHECK (MaxUsers IS NULL OR MaxUsers > 0),
    CONSTRAINT [CK_Plan_2] CHECK (MaxCompanies IS NULL OR MaxCompanies > 0),
    CONSTRAINT [CK_Plan_3] CHECK (MaxStorageGb IS NULL OR MaxStorageGb > 0)
);
GO
-- Modules included in a plan (replaces the Plan.IncludedModules JSON column)
CREATE TABLE [plat].[PlanModule] (
    [PlanId] INT NOT NULL,
    [ModuleCode] VARCHAR(12) NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_PlanModule_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_PlanModule] PRIMARY KEY CLUSTERED ([PlanId], [ModuleCode]),
    CONSTRAINT [CK_PlanModule_ModuleCode] CHECK ([ModuleCode] IS NULL OR [ModuleCode] IN ('CORE', 'INSTITUTIONS', 'FACILITIES', 'COVENANTS', 'WORKFLOW', 'LC_PURCHASE', 'LC_SALES', 'REQUESTS', 'REPORTS'))
);
GO
-- No direct access for the tenant application (it reads its row through plat.v_CurrentTenant); isolation root: the tenant (FR-PLT-001/002/046, BR-PLT-001/002)
CREATE TABLE [plat].[Tenant] (
    [TenantId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(30) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [PlanId] INT NOT NULL,
    [Status] VARCHAR(18) NOT NULL CONSTRAINT [DF_Tenant_Status] DEFAULT 'TRIAL',
    [TrialEndsOn] DATE NULL,
    [HomeCountryId] INT NOT NULL,
    [DefaultLanguage] VARCHAR(10) NOT NULL CONSTRAINT [DF_Tenant_DefaultLanguage] DEFAULT 'en',
    [TimeZone] VARCHAR(64) NOT NULL,
    [CalendarDisplay] VARCHAR(10) NOT NULL CONSTRAINT [DF_Tenant_CalendarDisplay] DEFAULT 'GREGORIAN',
    [DataRegion] VARCHAR(30) NULL,
    [SuspendedReason] NVARCHAR(MAX) NULL,
    [SuspendedAt] DATETIME2(3) NULL,
    [ActivatedAt] DATETIME2(3) NULL,
    [ClosedAt] DATETIME2(3) NULL,
    [ArchivedAt] DATETIME2(3) NULL,
    [MfaPolicy] VARCHAR(10) NOT NULL CONSTRAINT [DF_Tenant_MfaPolicy] DEFAULT 'PLATFORM',
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Tenant_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Tenant_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_Tenant] PRIMARY KEY CLUSTERED ([TenantId]),
    CONSTRAINT [UQ_Tenant_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Tenant_Code] UNIQUE ([Code]),
    CONSTRAINT [CK_Tenant_1] CHECK (Code COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Za-z0-9-]%' AND Code NOT LIKE '-%' AND Code NOT LIKE '%-'),
    CONSTRAINT [CK_Tenant_2] CHECK (Status <> 'TRIAL' OR TrialEndsOn IS NOT NULL),
    CONSTRAINT [CK_Tenant_3] CHECK (Status <> 'SUSPENDED' OR SuspendedReason IS NOT NULL),
    CONSTRAINT [CK_Tenant_4] CHECK (Status <> 'SUSPENDED' OR SuspendedAt IS NOT NULL),
    CONSTRAINT [CK_Tenant_5] CHECK (Status NOT IN ('CLOSED','ARCHIVED_READ_ONLY') OR ClosedAt IS NOT NULL),
    CONSTRAINT [CK_Tenant_6] CHECK (Status <> 'ARCHIVED_READ_ONLY' OR ArchivedAt IS NOT NULL),
    CONSTRAINT [CK_Tenant_7] CHECK (ArchivedAt IS NULL OR (ClosedAt IS NOT NULL AND ArchivedAt >= ClosedAt)),
    CONSTRAINT [CK_Tenant_Status] CHECK ([Status] IS NULL OR [Status] IN ('TRIAL', 'ACTIVE', 'SUSPENDED', 'CLOSED', 'ARCHIVED_READ_ONLY')),
    CONSTRAINT [CK_Tenant_DefaultLanguage] CHECK ([DefaultLanguage] IS NULL OR [DefaultLanguage] IN ('ar', 'en')),
    CONSTRAINT [CK_Tenant_CalendarDisplay] CHECK ([CalendarDisplay] IS NULL OR [CalendarDisplay] IN ('GREGORIAN', 'HIJRI', 'BOTH')),
    CONSTRAINT [CK_Tenant_MfaPolicy] CHECK ([MfaPolicy] IS NULL OR [MfaPolicy] IN ('PLATFORM', 'REQUIRED', 'OFF'))
);
GO
-- Subdomains reserved for the system: www, admin, api, app and others (FR-PLT-046)
CREATE TABLE [plat].[ReservedSubdomain] (
    [ReservedSubdomainId] INT IDENTITY(1,1) NOT NULL,
    [Subdomain] VARCHAR(63) NOT NULL,
    [Reason] NVARCHAR(200) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ReservedSubdomain_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_ReservedSubdomain] PRIMARY KEY CLUSTERED ([ReservedSubdomainId]),
    CONSTRAINT [UQ_ReservedSubdomain_Subdomain] UNIQUE ([Subdomain]),
    CONSTRAINT [CK_ReservedSubdomain_1] CHECK (Subdomain NOT LIKE '%[^a-z0-9-]%' AND Subdomain NOT LIKE '-%' AND Subdomain NOT LIKE '%-')
);
GO
-- Platform operator account: not readable by the tenant application (tp_app); identity store separate from AppUser (FR-PLT-006)
CREATE TABLE [plat].[PlatformOperator] (
    [PlatformOperatorId] INT IDENTITY(1,1) NOT NULL,
    [Email] NVARCHAR(254) NOT NULL,
    [DisplayName] NVARCHAR(200) NULL,
    [Role] VARCHAR(16) NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_PlatformOperator_Status] DEFAULT 'INVITED',
    [PasswordHash] VARCHAR(255) NULL,
    [PasswordChangedAt] DATETIME2(3) NULL,
    [MfaEnabled] BIT NOT NULL CONSTRAINT [DF_PlatformOperator_MfaEnabled] DEFAULT 0,
    [MfaSecretEnc] VARBINARY(256) NULL,
    [MfaKeyRef] VARCHAR(200) NULL,
    [MfaEnrolledAt] DATETIME2(3) NULL,
    [MfaLastUsedStep] BIGINT NULL,
    [FailedAttempts] INT NOT NULL CONSTRAINT [DF_PlatformOperator_FailedAttempts] DEFAULT 0,
    [FirstFailedAt] DATETIME2(3) NULL,
    [LockedUntil] DATETIME2(3) NULL,
    [LastLoginAt] DATETIME2(3) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_PlatformOperator_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_PlatformOperator_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_PlatformOperator] PRIMARY KEY CLUSTERED ([PlatformOperatorId]),
    CONSTRAINT [UQ_PlatformOperator_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_PlatformOperator_Email] UNIQUE ([Email]),
    CONSTRAINT [CK_PlatformOperator_1] CHECK (Status NOT IN ('ACTIVE','LOCKED') OR PasswordHash IS NOT NULL),
    CONSTRAINT [CK_PlatformOperator_2] CHECK (Status <> 'ACTIVE' OR MfaEnabled = 1),
    CONSTRAINT [CK_PlatformOperator_3] CHECK (MfaEnabled = 0 OR MfaSecretEnc IS NOT NULL),
    CONSTRAINT [CK_PlatformOperator_4] CHECK (MfaSecretEnc IS NULL OR MfaKeyRef IS NOT NULL),
    CONSTRAINT [CK_PlatformOperator_5] CHECK (MfaSecretEnc IS NULL OR DATALENGTH(MfaSecretEnc) >= 29),
    CONSTRAINT [CK_PlatformOperator_6] CHECK (FailedAttempts >= 0),
    CONSTRAINT [CK_PlatformOperator_7] CHECK (PasswordHash IS NULL OR PasswordHash LIKE '$argon2id$v=19$m=%,t=%,p=%$%$%'),
    CONSTRAINT [CK_PlatformOperator_Role] CHECK ([Role] IS NULL OR [Role] IN ('OPERATOR_ADMIN', 'OPERATOR_SUPPORT')),
    CONSTRAINT [CK_PlatformOperator_Status] CHECK ([Status] IS NULL OR [Status] IN ('INVITED', 'ACTIVE', 'LOCKED', 'DISABLED', 'ARCHIVED'))
);
GO
-- Modules enabled per tenant; owned by the platform only: written by platform operators, read by the tenant through a restricted view (DR-01)
CREATE TABLE [plat].[TenantModule] (
    [TenantModuleId] BIGINT IDENTITY(1,1) NOT NULL,
    [TenantId] INT NOT NULL,
    [ModuleCode] VARCHAR(12) NOT NULL,
    [IsEnabled] BIT NOT NULL CONSTRAINT [DF_TenantModule_IsEnabled] DEFAULT 1,
    [EnabledAt] DATETIME2(3) NULL,
    [EnabledBy] INT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TenantModule_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_TenantModule] PRIMARY KEY CLUSTERED ([TenantModuleId]),
    CONSTRAINT [UQ_TenantModule_TenantId_ModuleCode] UNIQUE ([TenantId], [ModuleCode]),
    CONSTRAINT [CK_TenantModule_1] CHECK (ModuleCode <> 'CORE' OR IsEnabled = 1),
    CONSTRAINT [CK_TenantModule_ModuleCode] CHECK ([ModuleCode] IS NULL OR [ModuleCode] IN ('CORE', 'INSTITUTIONS', 'FACILITIES', 'COVENANTS', 'WORKFLOW', 'LC_PURCHASE', 'LC_SALES', 'REQUESTS', 'REPORTS'))
);
GO
-- Temporary support access, activated by the tenant's account administrator (FR-PLT-007, BR-PLT-017)
CREATE TABLE [plat].[SupportAccessGrant] (
    [TenantId] INT NOT NULL,
    [SupportAccessGrantId] BIGINT IDENTITY(1,1) NOT NULL,
    [OperatorId] INT NOT NULL,
    [GrantedBy] BIGINT NOT NULL,
    [StartsAt] DATETIME2(3) NOT NULL,
    [EndsAt] DATETIME2(3) NOT NULL,
    [Reason] NVARCHAR(500) NOT NULL,
    [RevokedAt] DATETIME2(3) NULL,
    [RevokedBy] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SupportAccessGrant_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_SupportAccessGrant] PRIMARY KEY CLUSTERED ([SupportAccessGrantId]),
    CONSTRAINT [UQ_SupportAccessGrant_Tenant] UNIQUE ([TenantId], [SupportAccessGrantId]),
    CONSTRAINT [CK_SupportAccessGrant_1] CHECK (EndsAt > StartsAt),
    CONSTRAINT [CK_SupportAccessGrant_2] CHECK (EndsAt >= DATEADD(HOUR, 1, StartsAt) AND EndsAt <= DATEADD(HOUR, 72, StartsAt)),
    CONSTRAINT [CK_SupportAccessGrant_3] CHECK ((RevokedAt IS NULL AND RevokedBy IS NULL) OR (RevokedAt IS NOT NULL AND RevokedBy IS NOT NULL))
);
GO
-- One-time operator set-up links: password and MFA (FR-PLT-006)
CREATE TABLE [plat].[OperatorToken] (
    [OperatorTokenId] BIGINT IDENTITY(1,1) NOT NULL,
    [OperatorId] INT NOT NULL,
    [Purpose] VARCHAR(10) NOT NULL,
    [TokenHash] VARBINARY(32) NOT NULL,
    [ExpiresAt] DATETIME2(3) NOT NULL,
    [UsedAt] DATETIME2(3) NULL,
    [RevokedAt] DATETIME2(3) NULL,
    [SentTo] NVARCHAR(254) NULL,
    [RequestedBy] INT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_OperatorToken_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_OperatorToken] PRIMARY KEY CLUSTERED ([OperatorTokenId]),
    CONSTRAINT [UQ_OperatorToken_TokenHash] UNIQUE ([TokenHash]),
    CONSTRAINT [CK_OperatorToken_Purpose] CHECK ([Purpose] IS NULL OR [Purpose] IN ('INVITATION', 'RESET'))
);
GO
-- Platform operator sessions: 15-minute idle and 8-hour absolute timeout (FR-PLT-006)
CREATE TABLE [plat].[OperatorSession] (
    [OperatorSessionId] BIGINT IDENTITY(1,1) NOT NULL,
    [OperatorId] INT NOT NULL,
    [TokenHash] VARBINARY(32) NOT NULL,
    [LastSeenAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_OperatorSession_LastSeenAt] DEFAULT SYSUTCDATETIME(),
    [IdleExpiresAt] DATETIME2(3) NOT NULL,
    [AbsoluteExpiresAt] DATETIME2(3) NOT NULL,
    [MfaVerifiedAt] DATETIME2(3) NULL,
    [IpAddress] VARCHAR(45) NULL,
    [UserAgent] NVARCHAR(400) NULL,
    [EndedAt] DATETIME2(3) NULL,
    [EndReason] VARCHAR(19) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_OperatorSession_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_OperatorSession] PRIMARY KEY CLUSTERED ([OperatorSessionId]),
    CONSTRAINT [UQ_OperatorSession_TokenHash] UNIQUE ([TokenHash]),
    CONSTRAINT [CK_OperatorSession_1] CHECK ((EndedAt IS NULL AND EndReason IS NULL) OR (EndedAt IS NOT NULL AND EndReason IS NOT NULL)),
    CONSTRAINT [CK_OperatorSession_EndReason] CHECK ([EndReason] IS NULL OR [EndReason] IN ('LOGOUT', 'TERMINATED_BY_ADMIN', 'MFA_FAILED', 'OPERATOR_DISABLED', 'OPERATOR_RESET'))
);
GO
-- Blocked client address: automatic after repeated refusals, or set by an operator (docs/31 row 48)
CREATE TABLE [plat].[IpBlock] (
    [IpBlockId] BIGINT IDENTITY(1,1) NOT NULL,
    [ClientIp] VARCHAR(45) NOT NULL,
    [Source] VARCHAR(10) NOT NULL,
    [Reason] NVARCHAR(300) NOT NULL,
    [BlockedAt] DATETIME2(3) NOT NULL,
    [BlockedUntil] DATETIME2(3) NULL,
    [BlockedBy] INT NULL,
    [LiftedAt] DATETIME2(3) NULL,
    [LiftedBy] INT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_IpBlock_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_IpBlock_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_IpBlock] PRIMARY KEY CLUSTERED ([IpBlockId]),
    CONSTRAINT [UQ_IpBlock_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_IpBlock_1] CHECK (Source = 'MANUAL' OR (BlockedUntil IS NOT NULL AND BlockedBy IS NULL)),
    CONSTRAINT [CK_IpBlock_2] CHECK (Source = 'AUTO' OR BlockedBy IS NOT NULL),
    CONSTRAINT [CK_IpBlock_3] CHECK (BlockedUntil IS NULL OR BlockedUntil > BlockedAt),
    CONSTRAINT [CK_IpBlock_4] CHECK (LiftedAt IS NULL OR LiftedAt >= BlockedAt),
    CONSTRAINT [CK_IpBlock_Source] CHECK ([Source] IS NULL OR [Source] IN ('AUTO', 'MANUAL'))
);
GO
-- Security incident: detection, containment, root cause and corrective actions (DOC-S15)
CREATE TABLE [plat].[SecurityIncident] (
    [SecurityIncidentId] BIGINT IDENTITY(1,1) NOT NULL,
    [IncidentNo] VARCHAR(20) NOT NULL,
    [Title] NVARCHAR(200) NOT NULL,
    [Severity] VARCHAR(10) NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_SecurityIncident_Status] DEFAULT 'OPEN',
    [DetectedAt] DATETIME2(3) NOT NULL,
    [Description] NVARCHAR(4000) NOT NULL,
    [RootCause] NVARCHAR(4000) NULL,
    [Actions] NVARCHAR(4000) NULL,
    [ClientIps] NVARCHAR(1000) NULL,
    [OpenedBy] INT NOT NULL,
    [ClosedAt] DATETIME2(3) NULL,
    [ClosedBy] INT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SecurityIncident_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SecurityIncident_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_SecurityIncident] PRIMARY KEY CLUSTERED ([SecurityIncidentId]),
    CONSTRAINT [UQ_SecurityIncident_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_SecurityIncident_IncidentNo] UNIQUE ([IncidentNo]),
    CONSTRAINT [CK_SecurityIncident_1] CHECK ((Status = 'CLOSED' AND ClosedAt IS NOT NULL AND ClosedBy IS NOT NULL AND RootCause IS NOT NULL) OR (Status <> 'CLOSED' AND ClosedAt IS NULL AND ClosedBy IS NULL)),
    CONSTRAINT [CK_SecurityIncident_Severity] CHECK ([Severity] IS NULL OR [Severity] IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    CONSTRAINT [CK_SecurityIncident_Status] CHECK ([Status] IS NULL OR [Status] IN ('OPEN', 'CONTAINED', 'RESOLVED', 'CLOSED'))
);
GO
-- Journal of the schema scripts applied to this database (DOC-B11 section 6)
CREATE TABLE [plat].[SchemaMigration] (
    [SchemaMigrationId] BIGINT IDENTITY(1,1) NOT NULL,
    [Version] VARCHAR(60) NOT NULL,
    [Kind] VARCHAR(10) NOT NULL,
    [ScriptName] NVARCHAR(260) NOT NULL,
    [Checksum] VARBINARY(32) NOT NULL,
    [Fingerprint] VARBINARY(32) NOT NULL,
    [AppliedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SchemaMigration_AppliedAt] DEFAULT SYSUTCDATETIME(),
    [AppliedBy] NVARCHAR(128) NOT NULL,
    [DurationMs] INT NULL,
    [ChangeRef] VARCHAR(60) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SchemaMigration_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_SchemaMigration] PRIMARY KEY CLUSTERED ([SchemaMigrationId]),
    CONSTRAINT [CK_SchemaMigration_1] CHECK ((Kind = 'BASELINE' AND Version = 'BASELINE') OR (Kind = 'VERSIONED' AND Version LIKE 'V[0-9][0-9][0-9][0-9]') OR (Kind = 'REPEATABLE' AND Version = 'R')),
    CONSTRAINT [CK_SchemaMigration_2] CHECK (DurationMs IS NULL OR DurationMs >= 0),
    CONSTRAINT [CK_SchemaMigration_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('BASELINE', 'VERSIONED', 'REPEATABLE'))
);
GO

-- ===== schema sec =====
-- Tenant portal user (FR-PLT-010..016, BR-PLT-004..006)
CREATE TABLE [sec].[AppUser] (
    [TenantId] INT NOT NULL,
    [AppUserId] BIGINT IDENTITY(1,1) NOT NULL,
    [Email] NVARCHAR(254) NOT NULL,
    [DisplayNameAr] NVARCHAR(200) NULL,
    [DisplayNameEn] NVARCHAR(200) NULL,
    [DepartmentId] BIGINT NULL,
    [LineManagerUserId] BIGINT NULL,
    [CompanyScopeMode] VARCHAR(10) NOT NULL CONSTRAINT [DF_AppUser_CompanyScopeMode] DEFAULT 'SELECTED',
    [ProductScopeMode] VARCHAR(10) NOT NULL CONSTRAINT [DF_AppUser_ProductScopeMode] DEFAULT 'ALL',
    [EmployeeCode] VARCHAR(30) NULL,
    [Mobile] VARCHAR(16) NULL,
    [MustChangePassword] BIT NOT NULL CONSTRAINT [DF_AppUser_MustChangePassword] DEFAULT 0,
    [PreferredLanguage] VARCHAR(10) NULL,
    [DigitsPreference] VARCHAR(12) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_AppUser_Status] DEFAULT 'INVITED',
    [IsSystemUser] BIT NOT NULL CONSTRAINT [DF_AppUser_IsSystemUser] DEFAULT 0,
    [PasswordHash] VARCHAR(255) NULL,
    [PasswordChangedAt] DATETIME2(3) NULL,
    [MfaEnabled] BIT NOT NULL CONSTRAINT [DF_AppUser_MfaEnabled] DEFAULT 0,
    [MfaSecretEnc] VARBINARY(256) NULL,
    [MfaKeyPurpose] VARCHAR(11) NOT NULL CONSTRAINT [DF_AppUser_MfaKeyPurpose] DEFAULT 'DATA',
    [MfaKeyId] BIGINT NULL,
    [MfaEnrolledAt] DATETIME2(3) NULL,
    [MfaLastUsedStep] BIGINT NULL,
    [FailedAttempts] INT NOT NULL CONSTRAINT [DF_AppUser_FailedAttempts] DEFAULT 0,
    [FirstFailedAt] DATETIME2(3) NULL,
    [LockedUntil] DATETIME2(3) NULL,
    [LockoutCount] INT NOT NULL CONSTRAINT [DF_AppUser_LockoutCount] DEFAULT 0,
    [LastLockoutAt] DATETIME2(3) NULL,
    [RequiresAdminUnlock] BIT NOT NULL CONSTRAINT [DF_AppUser_RequiresAdminUnlock] DEFAULT 0,
    [LastLoginAt] DATETIME2(3) NULL,
    [ArchivedAt] DATETIME2(3) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_AppUser_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_AppUser_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_AppUser] PRIMARY KEY CLUSTERED ([AppUserId]),
    CONSTRAINT [UQ_AppUser_Tenant] UNIQUE ([TenantId], [AppUserId]),
    CONSTRAINT [UQ_AppUser_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_AppUser_Email] UNIQUE ([TenantId], [Email]),
    CONSTRAINT [CK_AppUser_1] CHECK (EmployeeCode IS NULL OR (LEN(EmployeeCode) >= 2 AND EmployeeCode COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Za-z0-9._-]%')),
    CONSTRAINT [CK_AppUser_2] CHECK (Mobile IS NULL OR (Mobile LIKE '+[1-9]%' AND LEN(Mobile) BETWEEN 9 AND 16 AND Mobile NOT LIKE '_%[^0-9]%')),
    CONSTRAINT [CK_AppUser_3] CHECK (LineManagerUserId IS NULL OR LineManagerUserId <> AppUserId),
    CONSTRAINT [CK_AppUser_4] CHECK (DisplayNameAr IS NOT NULL OR DisplayNameEn IS NOT NULL),
    CONSTRAINT [CK_AppUser_5] CHECK (IsSystemUser = 1 OR Status NOT IN ('ACTIVE','LOCKED') OR PasswordHash IS NOT NULL),
    CONSTRAINT [CK_AppUser_6] CHECK (MfaEnabled = 0 OR MfaSecretEnc IS NOT NULL),
    CONSTRAINT [CK_AppUser_7] CHECK (MfaSecretEnc IS NULL OR MfaKeyId IS NOT NULL),
    CONSTRAINT [CK_AppUser_8] CHECK (MfaSecretEnc IS NULL OR DATALENGTH(MfaSecretEnc) >= 29),
    CONSTRAINT [CK_AppUser_9] CHECK (IsSystemUser = 0 OR (PasswordHash IS NULL AND MfaEnabled = 0)),
    CONSTRAINT [CK_AppUser_10] CHECK (Status <> 'ARCHIVED' OR ArchivedAt IS NOT NULL),
    CONSTRAINT [CK_AppUser_11] CHECK (Status <> 'LOCKED' OR LockedUntil IS NOT NULL OR RequiresAdminUnlock = 1),
    CONSTRAINT [CK_AppUser_12] CHECK (FailedAttempts >= 0 AND LockoutCount >= 0),
    CONSTRAINT [CK_AppUser_13] CHECK (PasswordHash IS NULL OR PasswordHash LIKE '$argon2id$v=19$m=%,t=%,p=%$%$%'),
    CONSTRAINT [CK_AppUser_CompanyScopeMode] CHECK ([CompanyScopeMode] IS NULL OR [CompanyScopeMode] IN ('ALL', 'SELECTED')),
    CONSTRAINT [CK_AppUser_ProductScopeMode] CHECK ([ProductScopeMode] IS NULL OR [ProductScopeMode] IN ('ALL', 'SELECTED')),
    CONSTRAINT [CK_AppUser_PreferredLanguage] CHECK ([PreferredLanguage] IS NULL OR [PreferredLanguage] IN ('ar', 'en')),
    CONSTRAINT [CK_AppUser_DigitsPreference] CHECK ([DigitsPreference] IS NULL OR [DigitsPreference] IN ('WESTERN', 'ARABIC_INDIC')),
    CONSTRAINT [CK_AppUser_Status] CHECK ([Status] IS NULL OR [Status] IN ('INVITED', 'ACTIVE', 'LOCKED', 'DISABLED', 'ARCHIVED')),
    CONSTRAINT [CK_AppUser_MfaKeyPurpose] CHECK ([MfaKeyPurpose] IS NULL OR [MfaKeyPurpose] IN ('DATA'))
);
GO
-- Role defined by the tenant or seeded (FR-PLT-018)
CREATE TABLE [sec].[Role] (
    [TenantId] INT NOT NULL,
    [RoleId] BIGINT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(50) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [Description] NVARCHAR(MAX) NULL,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_Role_IsSystem] DEFAULT 0,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Role_IsActive] DEFAULT 1,
    [SeedKey] VARCHAR(80) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Role_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Role_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Role] PRIMARY KEY CLUSTERED ([RoleId]),
    CONSTRAINT [UQ_Role_Tenant] UNIQUE ([TenantId], [RoleId]),
    CONSTRAINT [UQ_Role_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Role_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_Role_1] CHECK (IsSystem = 0 OR SeedKey IS NOT NULL)
);
GO
-- Permission catalogue owned by the platform; a tenant cannot add a permission (FR-PLT-017)
CREATE TABLE [sec].[Permission] (
    [PermissionId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(100) NOT NULL,
    [ModuleCode] VARCHAR(12) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [Description] NVARCHAR(500) NULL,
    [IsSensitive] BIT NOT NULL CONSTRAINT [DF_Permission_IsSensitive] DEFAULT 0,
    [LockedToRoleCodes] NVARCHAR(MAX) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Permission_IsActive] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Permission_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_Permission] PRIMARY KEY CLUSTERED ([PermissionId]),
    CONSTRAINT [UQ_Permission_Code] UNIQUE ([Code]),
    CONSTRAINT [CK_Permission_1] CHECK (LockedToRoleCodes IS NULL OR IsSensitive = 1),
    CONSTRAINT [CK_Permission_ModuleCode] CHECK ([ModuleCode] IS NULL OR [ModuleCode] IN ('CORE', 'INSTITUTIONS', 'FACILITIES', 'COVENANTS', 'WORKFLOW', 'LC_PURCHASE', 'LC_SALES', 'REQUESTS', 'REPORTS')),
    CONSTRAINT [CK_Permission_LockedToRoleCodes_json] CHECK ([LockedToRoleCodes] IS NULL OR ISJSON([LockedToRoleCodes], VALUE) = 1)
);
GO
-- Role–permission link; a locked permission goes only to the system roles it names, enforced by sec.TR_RolePermission_Locked (043, BR-PLT-019, DR-16)
CREATE TABLE [sec].[RolePermission] (
    [TenantId] INT NOT NULL,
    [RoleId] BIGINT NOT NULL,
    [PermissionId] INT NOT NULL,
    [AssignedBy] BIGINT NULL,
    [AssignedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RolePermission_AssignedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RolePermission_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_RolePermission] PRIMARY KEY CLUSTERED ([TenantId], [RoleId], [PermissionId])
);
GO
-- User–role link; permissions are the union of the roles (BR-PLT-007, FR-PLT-018)
CREATE TABLE [sec].[UserRole] (
    [TenantId] INT NOT NULL,
    [UserId] BIGINT NOT NULL,
    [RoleId] BIGINT NOT NULL,
    [AssignedBy] BIGINT NULL,
    [AssignedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UserRole_AssignedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UserRole_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_UserRole] PRIMARY KEY CLUSTERED ([TenantId], [UserId], [RoleId])
);
GO
-- Companies a user can see; ignored when CompanyScopeMode = ALL (FR-PLT-020)
CREATE TABLE [sec].[UserCompanyScope] (
    [TenantId] INT NOT NULL,
    [UserId] BIGINT NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [IncludeDescendants] BIT NOT NULL CONSTRAINT [DF_UserCompanyScope_IncludeDescendants] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UserCompanyScope_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_UserCompanyScope] PRIMARY KEY CLUSTERED ([TenantId], [UserId], [CompanyId])
);
GO
-- Login attempts for rate limiting and lockout windows (BR-PLT-005); written by sec.usp_StartSession. A permanent trace in aud.AuditLog is not written yet (O-24)
CREATE TABLE [sec].[LoginAttempt] (
    [TenantId] INT NOT NULL,
    [LoginAttemptId] BIGINT IDENTITY(1,1) NOT NULL,
    [UserId] BIGINT NULL,
    [LoginName] NVARCHAR(200) NULL,
    [Outcome] VARCHAR(15) NOT NULL,
    [IpAddress] VARCHAR(45) NULL,
    [UserAgent] NVARCHAR(400) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LoginAttempt_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_LoginAttempt] PRIMARY KEY CLUSTERED ([LoginAttemptId]),
    CONSTRAINT [UQ_LoginAttempt_Tenant] UNIQUE ([TenantId], [LoginAttemptId]),
    CONSTRAINT [CK_LoginAttempt_1] CHECK (UserId IS NOT NULL OR LoginName IS NOT NULL),
    CONSTRAINT [CK_LoginAttempt_Outcome] CHECK ([Outcome] IS NULL OR [Outcome] IN ('LOGIN_SUCCESS', 'FAILED_PASSWORD', 'DENIED_LOCKED', 'DENIED_TENANT', 'FAILED_MFA', 'LOCKOUT'))
);
GO
-- Connection binding for the row filters (O-16)
CREATE TABLE [sec].[SessionBinding] (
    [SessionId] INT NOT NULL,
    [BoundTenantId] INT NOT NULL,
    [BoundUserId] BIGINT NOT NULL,
    [BindingToken] UNIQUEIDENTIFIER NOT NULL,
    [BoundAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SessionBinding_BoundAt] DEFAULT SYSUTCDATETIME(),
    [BindingKind] VARCHAR(10) NOT NULL CONSTRAINT [DF_SessionBinding_BindingKind] DEFAULT 'USER',
    [BoundOperatorId] INT NULL,
    CONSTRAINT [PK_SessionBinding] PRIMARY KEY CLUSTERED ([SessionId]),
    CONSTRAINT [CK_SessionBinding_1] CHECK ((BindingKind = 'SUPPORT' AND BoundOperatorId IS NOT NULL) OR (BindingKind <> 'SUPPORT' AND BoundOperatorId IS NULL)),
    CONSTRAINT [CK_SessionBinding_BindingKind] CHECK ([BindingKind] IS NULL OR [BindingKind] IN ('USER', 'JOB', 'SUPPORT'))
);
GO
-- Products (modules) a user may use; ignored when ProductScopeMode = ALL (docs/31 row 46, ADR 0048)
CREATE TABLE [sec].[UserProductScope] (
    [TenantId] INT NOT NULL,
    [UserId] BIGINT NOT NULL,
    [ModuleCode] VARCHAR(12) NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UserProductScope_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_UserProductScope] PRIMARY KEY CLUSTERED ([TenantId], [UserId], [ModuleCode]),
    CONSTRAINT [CK_UserProductScope_ModuleCode] CHECK ([ModuleCode] IS NULL OR [ModuleCode] IN ('CORE', 'INSTITUTIONS', 'FACILITIES', 'COVENANTS', 'WORKFLOW', 'LC_PURCHASE', 'LC_SALES', 'REQUESTS', 'REPORTS'))
);
GO
-- User sessions: 30-minute idle timeout and 12-hour absolute timeout (FR-PLT-014)
CREATE TABLE [sec].[UserSession] (
    [TenantId] INT NOT NULL,
    [UserSessionId] BIGINT IDENTITY(1,1) NOT NULL,
    [UserId] BIGINT NOT NULL,
    [MfaRequired] BIT NOT NULL CONSTRAINT [DF_UserSession_MfaRequired] DEFAULT 1,
    [TokenHash] VARBINARY(32) NOT NULL,
    [LastSeenAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UserSession_LastSeenAt] DEFAULT SYSUTCDATETIME(),
    [IdleExpiresAt] DATETIME2(3) NOT NULL,
    [AbsoluteExpiresAt] DATETIME2(3) NOT NULL,
    [MfaVerifiedAt] DATETIME2(3) NULL,
    [IpAddress] VARCHAR(45) NULL,
    [UserAgent] NVARCHAR(400) NULL,
    [EndedAt] DATETIME2(3) NULL,
    [EndReason] VARCHAR(19) NULL,
    [EndedBy] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UserSession_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_UserSession] PRIMARY KEY CLUSTERED ([UserSessionId]),
    CONSTRAINT [UQ_UserSession_Tenant] UNIQUE ([TenantId], [UserSessionId]),
    CONSTRAINT [UQ_UserSession_TokenHash] UNIQUE ([TenantId], [TokenHash]),
    CONSTRAINT [CK_UserSession_1] CHECK ((EndedAt IS NULL AND EndReason IS NULL) OR (EndedAt IS NOT NULL AND EndReason IS NOT NULL)),
    CONSTRAINT [CK_UserSession_EndReason] CHECK ([EndReason] IS NULL OR [EndReason] IN ('LOGOUT', 'IDLE_TIMEOUT', 'ABSOLUTE_TIMEOUT', 'TERMINATED_BY_ADMIN', 'PASSWORD_CHANGED', 'MFA_RESET', 'MFA_FAILED', 'USER_DISABLED', 'TENANT_SUSPENDED'))
);
GO
-- Ten single-use recovery codes, stored hashed (FR-PLT-011, BR-PLT-006); replaces the AppUser.RecoveryCodesHash JSON
CREATE TABLE [sec].[MfaRecoveryCode] (
    [TenantId] INT NOT NULL,
    [MfaRecoveryCodeId] BIGINT IDENTITY(1,1) NOT NULL,
    [UserId] BIGINT NOT NULL,
    [CodeHash] VARBINARY(32) NOT NULL,
    [UsedAt] DATETIME2(3) NULL,
    [UsedIp] VARCHAR(45) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_MfaRecoveryCode_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_MfaRecoveryCode] PRIMARY KEY CLUSTERED ([MfaRecoveryCodeId]),
    CONSTRAINT [UQ_MfaRecoveryCode_Tenant] UNIQUE ([TenantId], [MfaRecoveryCodeId]),
    CONSTRAINT [UQ_MfaRecoveryCode_UserId_CodeHash] UNIQUE ([TenantId], [UserId], [CodeHash])
);
GO
-- Single-use invitation link (48 hours), password-reset token (30 minutes) or MFA re-enrolment link (24 hours) (FR-PLT-013, DQ-F03-8)
CREATE TABLE [sec].[UserToken] (
    [TenantId] INT NOT NULL,
    [UserTokenId] BIGINT IDENTITY(1,1) NOT NULL,
    [UserId] BIGINT NOT NULL,
    [Purpose] VARCHAR(15) NOT NULL,
    [TokenHash] VARBINARY(32) NOT NULL,
    [ExpiresAt] DATETIME2(3) NOT NULL,
    [UsedAt] DATETIME2(3) NULL,
    [RevokedAt] DATETIME2(3) NULL,
    [SentTo] NVARCHAR(254) NULL,
    [SendStatus] VARCHAR(10) NOT NULL CONSTRAINT [DF_UserToken_SendStatus] DEFAULT 'PENDING',
    [SendError] NVARCHAR(500) NULL,
    [RequestedByUserId] BIGINT NULL,
    [RequestIp] VARCHAR(45) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UserToken_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_UserToken] PRIMARY KEY CLUSTERED ([UserTokenId]),
    CONSTRAINT [UQ_UserToken_Tenant] UNIQUE ([TenantId], [UserTokenId]),
    CONSTRAINT [UQ_UserToken_TokenHash] UNIQUE ([TenantId], [TokenHash]),
    CONSTRAINT [CK_UserToken_Purpose] CHECK ([Purpose] IS NULL OR [Purpose] IN ('INVITATION', 'PASSWORD_RESET', 'MFA_REENROLMENT')),
    CONSTRAINT [CK_UserToken_SendStatus] CHECK ([SendStatus] IS NULL OR [SendStatus] IN ('PENDING', 'SENT', 'FAILED'))
);
GO
-- Last five passwords, to prevent reuse (BR-PLT-004)
CREATE TABLE [sec].[UserPasswordHistory] (
    [TenantId] INT NOT NULL,
    [UserPasswordHistoryId] BIGINT IDENTITY(1,1) NOT NULL,
    [UserId] BIGINT NOT NULL,
    [PasswordHash] VARCHAR(255) NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UserPasswordHistory_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_UserPasswordHistory] PRIMARY KEY CLUSTERED ([UserPasswordHistoryId]),
    CONSTRAINT [UQ_UserPasswordHistory_Tenant] UNIQUE ([TenantId], [UserPasswordHistoryId]),
    CONSTRAINT [CK_UserPasswordHistory_1] CHECK (PasswordHash LIKE '$argon2id$v=19$m=%,t=%,p=%$%$%')
);
GO
-- Link between an external OIDC or Entra identity and a user; readiness only (FR-PLT-015, section 11)
CREATE TABLE [sec].[ExternalIdentity] (
    [TenantId] INT NOT NULL,
    [ExternalIdentityId] BIGINT IDENTITY(1,1) NOT NULL,
    [UserId] BIGINT NOT NULL,
    [Provider] VARCHAR(10) NOT NULL,
    [Issuer] VARCHAR(300) NOT NULL,
    [Subject] NVARCHAR(200) NOT NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_ExternalIdentity_IsActive] DEFAULT 1,
    [LastLoginAt] DATETIME2(3) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ExternalIdentity_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ExternalIdentity] PRIMARY KEY CLUSTERED ([ExternalIdentityId]),
    CONSTRAINT [UQ_ExternalIdentity_Tenant] UNIQUE ([TenantId], [ExternalIdentityId]),
    CONSTRAINT [UQ_ExternalIdentity_Issuer_Subject] UNIQUE ([TenantId], [Issuer], [Subject]),
    CONSTRAINT [UQ_ExternalIdentity_UserId_Provider_Issuer] UNIQUE ([TenantId], [UserId], [Provider], [Issuer]),
    CONSTRAINT [CK_ExternalIdentity_Provider] CHECK ([Provider] IS NULL OR [Provider] IN ('OIDC', 'ENTRA_ID'))
);
GO
-- Tenant key register; each key is wrapped by a master key held outside the database (FR-PLT-037, BR-PLT-015)
CREATE TABLE [sec].[TenantKey] (
    [TenantId] INT NOT NULL,
    [TenantKeyId] BIGINT IDENTITY(1,1) NOT NULL,
    [Purpose] VARCHAR(11) NOT NULL,
    [KeyVersion] INT NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_TenantKey_Status] DEFAULT 'PENDING',
    [Algorithm] VARCHAR(30) NOT NULL CONSTRAINT [DF_TenantKey_Algorithm] DEFAULT 'AES-256-GCM',
    [WrappedKey] VARBINARY(512) NOT NULL,
    [MasterKeyRef] VARCHAR(200) NOT NULL,
    [ActivatedAt] DATETIME2(3) NULL,
    [RetiredAt] DATETIME2(3) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TenantKey_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TenantKey] PRIMARY KEY CLUSTERED ([TenantKeyId]),
    CONSTRAINT [UQ_TenantKey_Tenant] UNIQUE ([TenantId], [TenantKeyId]),
    CONSTRAINT [UQ_TenantKey_Scope_Purpose] UNIQUE ([TenantId], [Purpose], [TenantKeyId]),
    CONSTRAINT [UQ_TenantKey_Purpose_KeyVersion] UNIQUE ([TenantId], [Purpose], [KeyVersion]),
    CONSTRAINT [CK_TenantKey_1] CHECK (KeyVersion >= 1),
    CONSTRAINT [CK_TenantKey_2] CHECK (Status NOT IN ('ACTIVE','RETIRING','RETIRED') OR ActivatedAt IS NOT NULL),
    CONSTRAINT [CK_TenantKey_3] CHECK (Status <> 'RETIRED' OR RetiredAt IS NOT NULL),
    CONSTRAINT [CK_TenantKey_Purpose] CHECK ([Purpose] IS NULL OR [Purpose] IN ('DATA', 'BLIND_INDEX', 'FILE')),
    CONSTRAINT [CK_TenantKey_Status] CHECK ([Status] IS NULL OR [Status] IN ('PENDING', 'ACTIVE', 'RETIRING', 'RETIRED', 'REVOKED'))
);
GO
-- Key event log: create, rotate and revoke (FR-PLT-037; high severity BR-PLT-009)
CREATE TABLE [sec].[KeyEvent] (
    [TenantId] INT NOT NULL,
    [KeyEventId] BIGINT IDENTITY(1,1) NOT NULL,
    [TenantKeyId] BIGINT NULL,
    [EventType] VARCHAR(18) NOT NULL,
    [ActorType] VARCHAR(10) NOT NULL CONSTRAINT [DF_KeyEvent_ActorType] DEFAULT 'SYSTEM',
    [ActorId] UNIQUEIDENTIFIER NULL,
    [Result] VARCHAR(10) NOT NULL CONSTRAINT [DF_KeyEvent_Result] DEFAULT 'SUCCESS',
    [Detail] NVARCHAR(MAX) NULL,
    [CorrelationId] UNIQUEIDENTIFIER NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_KeyEvent_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_KeyEvent] PRIMARY KEY CLUSTERED ([KeyEventId]),
    CONSTRAINT [UQ_KeyEvent_Tenant] UNIQUE ([TenantId], [KeyEventId]),
    CONSTRAINT [CK_KeyEvent_EventType] CHECK ([EventType] IS NULL OR [EventType] IN ('CREATED', 'ACTIVATED', 'ROTATION_STARTED', 'ROTATION_COMPLETED', 'RETIRED', 'REVOKED', 'UNWRAP_FAILED', 'MASTER_KEY_CHANGED', 'BACKUP_VERIFIED')),
    CONSTRAINT [CK_KeyEvent_ActorType] CHECK ([ActorType] IS NULL OR [ActorType] IN ('USER', 'OPERATOR', 'SYSTEM', 'JOB')),
    CONSTRAINT [CK_KeyEvent_Result] CHECK ([Result] IS NULL OR [Result] IN ('SUCCESS', 'FAILED'))
);
GO

-- ===== schema aud =====
-- Append-only audit log; NULL TenantId = platform event, not visible to any tenant; dedicated RLS policy (BR-PLT-001, BR-PLT-009)
CREATE TABLE [aud].[AuditLog] (
    [TenantId] INT NULL,
    [AuditLogId] BIGINT IDENTITY(1,1) NOT NULL,
    [ChainSeq] BIGINT NULL,
    [OccurredAt] DATETIME2(3) NOT NULL,
    [ActorType] VARCHAR(10) NOT NULL,
    [ActorId] UNIQUEIDENTIFIER NULL,
    [Action] VARCHAR(60) NOT NULL,
    [Category] VARCHAR(15) NOT NULL CONSTRAINT [DF_AuditLog_Category] DEFAULT 'SYSTEM',
    [Severity] VARCHAR(10) NOT NULL CONSTRAINT [DF_AuditLog_Severity] DEFAULT 'INFO',
    [EntityType] VARCHAR(60) NULL,
    [EntityId] BIGINT NULL,
    [CompanyId] BIGINT NULL,
    [BeforeJson] NVARCHAR(MAX) NULL,
    [AfterJson] NVARCHAR(MAX) NULL,
    [CorrelationId] UNIQUEIDENTIFIER NULL,
    [IpAddress] VARCHAR(45) NULL,
    [UserAgent] NVARCHAR(400) NULL,
    [Result] VARCHAR(10) NOT NULL CONSTRAINT [DF_AuditLog_Result] DEFAULT 'SUCCESS',
    [PrevHash] VARBINARY(32) NULL,
    [RowHash] VARBINARY(32) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_AuditLog_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_AuditLog] PRIMARY KEY CLUSTERED ([AuditLogId]),
    CONSTRAINT [UQ_AuditLog_Tenant] UNIQUE ([TenantId], [AuditLogId]),
    CONSTRAINT [CK_AuditLog_ActorType] CHECK ([ActorType] IS NULL OR [ActorType] IN ('USER', 'OPERATOR', 'SYSTEM', 'JOB')),
    CONSTRAINT [CK_AuditLog_Category] CHECK ([Category] IS NULL OR [Category] IN ('SECURITY', 'CONFIG', 'TREASURY', 'IDENTITY_ACCESS', 'PLATFORM', 'SYSTEM')),
    CONSTRAINT [CK_AuditLog_Severity] CHECK ([Severity] IS NULL OR [Severity] IN ('INFO', 'HIGH')),
    CONSTRAINT [CK_AuditLog_Result] CHECK ([Result] IS NULL OR [Result] IN ('SUCCESS', 'DENIED', 'FAILED')),
    CONSTRAINT [CK_AuditLog_BeforeJson_json] CHECK ([BeforeJson] IS NULL OR ISJSON([BeforeJson], VALUE) = 1),
    CONSTRAINT [CK_AuditLog_AfterJson_json] CHECK ([AfterJson] IS NULL OR ISJSON([AfterJson], VALUE) = 1)
);
GO
-- Access log for sensitive data: identity reveals, image views, exports and restricted downloads; flags anomalies above 20 per hour (BR-PTY-009)
CREATE TABLE [aud].[SensitiveAccessLog] (
    [TenantId] INT NOT NULL,
    [SensitiveAccessLogId] BIGINT IDENTITY(1,1) NOT NULL,
    [OccurredAt] DATETIME2(3) NOT NULL,
    [AccessKind] VARCHAR(27) NOT NULL,
    [ActorType] VARCHAR(10) NOT NULL CONSTRAINT [DF_SensitiveAccessLog_ActorType] DEFAULT 'USER',
    [ActorUserId] BIGINT NULL,
    [OperatorId] INT NULL,
    [SubjectEntityType] VARCHAR(60) NOT NULL,
    [SubjectEntityId] BIGINT NOT NULL,
    [SubjectPartyId] BIGINT NULL,
    [CompanyId] BIGINT NULL,
    [Result] VARCHAR(10) NOT NULL,
    [DenyReason] VARCHAR(40) NULL,
    [Reason] NVARCHAR(300) NULL,
    [IpAddress] VARCHAR(45) NULL,
    [UserAgent] NVARCHAR(400) NULL,
    [CorrelationId] UNIQUEIDENTIFIER NULL,
    [AuditLogId] BIGINT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SensitiveAccessLog_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_SensitiveAccessLog] PRIMARY KEY CLUSTERED ([SensitiveAccessLogId]),
    CONSTRAINT [UQ_SensitiveAccessLog_Tenant] UNIQUE ([TenantId], [SensitiveAccessLogId]),
    CONSTRAINT [CK_SensitiveAccessLog_1] CHECK (ActorType <> 'USER' OR ActorUserId IS NOT NULL),
    CONSTRAINT [CK_SensitiveAccessLog_2] CHECK (ActorType <> 'OPERATOR' OR OperatorId IS NOT NULL),
    CONSTRAINT [CK_SensitiveAccessLog_3] CHECK (Result = 'GRANTED' OR DenyReason IS NOT NULL),
    CONSTRAINT [CK_SensitiveAccessLog_AccessKind] CHECK ([AccessKind] IS NULL OR [AccessKind] IN ('IDENTITY_REVEAL', 'IDENTITY_IMAGE_VIEW', 'SENSITIVE_DOCUMENT_DOWNLOAD', 'PACK_EXPORT', 'SENSITIVE_EXPORT', 'DATA_EXPORT', 'CUSTOM_FIELD_REVEAL')),
    CONSTRAINT [CK_SensitiveAccessLog_ActorType] CHECK ([ActorType] IS NULL OR [ActorType] IN ('USER', 'OPERATOR', 'SYSTEM')),
    CONSTRAINT [CK_SensitiveAccessLog_Result] CHECK ([Result] IS NULL OR [Result] IN ('GRANTED', 'DENIED'))
);
GO
-- Head of each audit hash chain: its last sequence number and hash (FR-PLT-025)
CREATE TABLE [aud].[AuditChainHead] (
    [ChainKey] INT NOT NULL,
    [LastSeq] BIGINT NOT NULL,
    [LastHash] VARBINARY(32) NOT NULL,
    CONSTRAINT [PK_AuditChainHead] PRIMARY KEY CLUSTERED ([ChainKey]),
    CONSTRAINT [CK_AuditChainHead_1] CHECK (ChainKey >= 0),
    CONSTRAINT [CK_AuditChainHead_2] CHECK (LastSeq >= 1)
);
GO
-- Anchor of an audit chain: its head at a moment, also kept outside the database (DOC-S12 section 5.3)
CREATE TABLE [aud].[AuditChainAnchor] (
    [AuditChainAnchorId] BIGINT IDENTITY(1,1) NOT NULL,
    [ChainKey] INT NOT NULL,
    [ChainSeq] BIGINT NOT NULL,
    [RowHash] VARBINARY(32) NOT NULL,
    [TakenAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_AuditChainAnchor_TakenAt] DEFAULT SYSUTCDATETIME(),
    [StoreRef] NVARCHAR(400) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_AuditChainAnchor_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_AuditChainAnchor] PRIMARY KEY CLUSTERED ([AuditChainAnchorId]),
    CONSTRAINT [CK_AuditChainAnchor_1] CHECK (ChainSeq >= 1)
);
GO

-- ===== schema doc =====
-- Logical document: document data and status; the file itself is in doc.DocumentVersion (FR-PLT-027/028, BR-PLT-011)
CREATE TABLE [doc].[Document] (
    [TenantId] INT NOT NULL,
    [DocumentId] BIGINT IDENTITY(1,1) NOT NULL,
    [DocumentTypeId] INT NOT NULL,
    [Title] NVARCHAR(200) NOT NULL,
    [DocumentNumber] NVARCHAR(100) NULL,
    [IssueDate] DATE NULL,
    [IssueDateHijriText] NVARCHAR(20) NULL,
    [ExpiryDate] DATE NULL,
    [ExpiryDateHijriText] NVARCHAR(20) NULL,
    [IssuingAuthority] NVARCHAR(200) NULL,
    [OwnerCompanyId] BIGINT NULL,
    [Sensitivity] VARCHAR(12) NOT NULL CONSTRAINT [DF_Document_Sensitivity] DEFAULT 'CONFIDENTIAL',
    [Status] VARCHAR(12) NOT NULL CONSTRAINT [DF_Document_Status] DEFAULT 'ACTIVE',
    [CurrentVersionId] BIGINT NULL,
    [SupersededByDocumentId] BIGINT NULL,
    [DeletedAt] DATETIME2(3) NULL,
    [DeletedBy] BIGINT NULL,
    [DeleteReason] NVARCHAR(500) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Document_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Document_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Document] PRIMARY KEY CLUSTERED ([DocumentId]),
    CONSTRAINT [UQ_Document_Tenant] UNIQUE ([TenantId], [DocumentId]),
    CONSTRAINT [UQ_Document_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_Document_1] CHECK (IssueDate IS NULL OR ExpiryDate IS NULL OR ExpiryDate > IssueDate),
    CONSTRAINT [CK_Document_2] CHECK (Status <> 'SUPERSEDED' OR SupersededByDocumentId IS NOT NULL),
    CONSTRAINT [CK_Document_3] CHECK (Status <> 'SOFT_DELETED' OR (DeletedAt IS NOT NULL AND DeleteReason IS NOT NULL)),
    CONSTRAINT [CK_Document_4] CHECK (SupersededByDocumentId IS NULL OR SupersededByDocumentId <> DocumentId),
    CONSTRAINT [CK_Document_5] CHECK (Sensitivity <> 'PUBLIC'),
    CONSTRAINT [CK_Document_Sensitivity] CHECK ([Sensitivity] IS NULL OR [Sensitivity] IN ('PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED')),
    CONSTRAINT [CK_Document_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'SUPERSEDED', 'SOFT_DELETED'))
);
GO
-- Immutable file version; a change creates a new version: the application may update only the scan and integrity columns (043, FR-PLT-027, BR-PLT-011, DR-11)
CREATE TABLE [doc].[DocumentVersion] (
    [TenantId] INT NOT NULL,
    [DocumentVersionId] BIGINT IDENTITY(1,1) NOT NULL,
    [DocumentId] BIGINT NOT NULL,
    [VersionNo] INT NOT NULL,
    [StorageKey] VARCHAR(300) NOT NULL,
    [FileName] NVARCHAR(260) NULL,
    [ContentType] VARCHAR(150) NULL,
    [SizeBytes] BIGINT NOT NULL,
    [Sha256] VARBINARY(32) NOT NULL,
    [KeyPurpose] VARCHAR(11) NOT NULL CONSTRAINT [DF_DocumentVersion_KeyPurpose] DEFAULT 'FILE',
    [KeyId] BIGINT NOT NULL,
    [ScanStatus] VARCHAR(11) NOT NULL CONSTRAINT [DF_DocumentVersion_ScanStatus] DEFAULT 'PENDING',
    [ScannedAt] DATETIME2(3) NULL,
    [ScanDetail] NVARCHAR(300) NULL,
    [IntegrityStatus] VARCHAR(10) NOT NULL CONSTRAINT [DF_DocumentVersion_IntegrityStatus] DEFAULT 'UNVERIFIED',
    [LastVerifiedAt] DATETIME2(3) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_DocumentVersion_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_DocumentVersion] PRIMARY KEY CLUSTERED ([DocumentVersionId]),
    CONSTRAINT [UQ_DocumentVersion_Tenant] UNIQUE ([TenantId], [DocumentVersionId]),
    CONSTRAINT [UQ_DocumentVersion_Scope_DocumentId] UNIQUE ([TenantId], [DocumentId], [DocumentVersionId]),
    CONSTRAINT [UQ_DocumentVersion_DocumentId_VersionNo] UNIQUE ([TenantId], [DocumentId], [VersionNo]),
    CONSTRAINT [UQ_DocumentVersion_StorageKey] UNIQUE ([StorageKey]),
    CONSTRAINT [CK_DocumentVersion_1] CHECK (VersionNo >= 1),
    CONSTRAINT [CK_DocumentVersion_2] CHECK (SizeBytes > 0),
    CONSTRAINT [CK_DocumentVersion_3] CHECK (ScanStatus = 'PENDING' OR ScannedAt IS NOT NULL),
    CONSTRAINT [CK_DocumentVersion_KeyPurpose] CHECK ([KeyPurpose] IS NULL OR [KeyPurpose] IN ('FILE')),
    CONSTRAINT [CK_DocumentVersion_ScanStatus] CHECK ([ScanStatus] IS NULL OR [ScanStatus] IN ('PENDING', 'CLEAN', 'QUARANTINED')),
    CONSTRAINT [CK_DocumentVersion_IntegrityStatus] CHECK ([IntegrityStatus] IS NULL OR [IntegrityStatus] IN ('UNVERIFIED', 'OK', 'MISMATCH', 'MISSING'))
);
GO
-- Links a document to any entity with a role and a reference page; unlinking is logical (FR-PLT-028)
CREATE TABLE [doc].[DocumentLink] (
    [TenantId] INT NOT NULL,
    [DocumentLinkId] BIGINT IDENTITY(1,1) NOT NULL,
    [DocumentId] BIGINT NOT NULL,
    [EntityType] VARCHAR(60) NOT NULL,
    [EntityId] BIGINT NOT NULL,
    [LinkRole] VARCHAR(11) NOT NULL CONSTRAINT [DF_DocumentLink_LinkRole] DEFAULT 'ATTACHMENT',
    [PageRef] NVARCHAR(30) NULL,
    [UnlinkedAt] DATETIME2(3) NULL,
    [UnlinkedBy] BIGINT NULL,
    [UnlinkReason] NVARCHAR(300) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_DocumentLink_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_DocumentLink] PRIMARY KEY CLUSTERED ([DocumentLinkId]),
    CONSTRAINT [UQ_DocumentLink_Tenant] UNIQUE ([TenantId], [DocumentLinkId]),
    CONSTRAINT [CK_DocumentLink_1] CHECK ((UnlinkedAt IS NULL AND UnlinkedBy IS NULL) OR (UnlinkedAt IS NOT NULL AND UnlinkedBy IS NOT NULL)),
    CONSTRAINT [CK_DocumentLink_LinkRole] CHECK ([LinkRole] IS NULL OR [LinkRole] IN ('SOURCE', 'ATTACHMENT', 'IMAGE_FRONT', 'IMAGE_BACK', 'IMAGE_OTHER'))
);
GO

-- ===== schema cfg =====
-- Setting-key definition with platform minimum and maximum bounds (BR-PLT-018, FR-PLT-043)
CREATE TABLE [cfg].[SettingDefinition] (
    [SettingDefinitionId] INT IDENTITY(1,1) NOT NULL,
    [Key] VARCHAR(100) NOT NULL,
    [ModuleCode] VARCHAR(12) NOT NULL CONSTRAINT [DF_SettingDefinition_ModuleCode] DEFAULT 'CORE',
    [ValueType] VARCHAR(10) NOT NULL,
    [DefaultValueJson] NVARCHAR(MAX) NOT NULL,
    [MinValueJson] NVARCHAR(MAX) NULL,
    [MaxValueJson] NVARCHAR(MAX) NULL,
    [IsSecurity] BIT NOT NULL CONSTRAINT [DF_SettingDefinition_IsSecurity] DEFAULT 0,
    [IsTenantEditable] BIT NOT NULL CONSTRAINT [DF_SettingDefinition_IsTenantEditable] DEFAULT 1,
    [Description] NVARCHAR(500) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SettingDefinition_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_SettingDefinition] PRIMARY KEY CLUSTERED ([SettingDefinitionId]),
    CONSTRAINT [UQ_SettingDefinition_Key] UNIQUE ([Key]),
    CONSTRAINT [CK_SettingDefinition_ModuleCode] CHECK ([ModuleCode] IS NULL OR [ModuleCode] IN ('CORE', 'INSTITUTIONS', 'FACILITIES', 'COVENANTS', 'WORKFLOW', 'LC_PURCHASE', 'LC_SALES', 'REQUESTS', 'REPORTS')),
    CONSTRAINT [CK_SettingDefinition_ValueType] CHECK ([ValueType] IS NULL OR [ValueType] IN ('STRING', 'INT', 'DECIMAL', 'BOOL', 'TIME', 'DURATION', 'JSON')),
    CONSTRAINT [CK_SettingDefinition_DefaultValueJson_json] CHECK ([DefaultValueJson] IS NULL OR ISJSON([DefaultValueJson], VALUE) = 1),
    CONSTRAINT [CK_SettingDefinition_MinValueJson_json] CHECK ([MinValueJson] IS NULL OR ISJSON([MinValueJson], VALUE) = 1),
    CONSTRAINT [CK_SettingDefinition_MaxValueJson_json] CHECK ([MaxValueJson] IS NULL OR ISJSON([MaxValueJson], VALUE) = 1)
);
GO
-- Tenant settings: security policies, timeouts, thresholds, and work start and end times (FR-PLT-043)
CREATE TABLE [cfg].[TenantSetting] (
    [TenantId] INT NOT NULL,
    [TenantSettingId] BIGINT IDENTITY(1,1) NOT NULL,
    [Key] VARCHAR(100) NOT NULL,
    [ValueJson] NVARCHAR(MAX) NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TenantSetting_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TenantSetting] PRIMARY KEY CLUSTERED ([TenantSettingId]),
    CONSTRAINT [UQ_TenantSetting_Tenant] UNIQUE ([TenantId], [TenantSettingId]),
    CONSTRAINT [UQ_TenantSetting_Key] UNIQUE ([TenantId], [Key]),
    CONSTRAINT [CK_TenantSetting_ValueJson_json] CHECK ([ValueJson] IS NULL OR ISJSON([ValueJson], VALUE) = 1)
);
GO
-- Numbering-type definition with a tag-based format, for example {seq:000}-{erp}-{yy} (FR-PLT-026)
CREATE TABLE [cfg].[NumberSequenceDefinition] (
    [TenantId] INT NOT NULL,
    [NumberSequenceDefinitionId] BIGINT IDENTITY(1,1) NOT NULL,
    [SequenceKey] VARCHAR(50) NOT NULL,
    [Pattern] NVARCHAR(100) NOT NULL,
    [ScopeLevel] VARCHAR(10) NOT NULL CONSTRAINT [DF_NumberSequenceDefinition_ScopeLevel] DEFAULT 'TENANT',
    [PeriodBasis] VARCHAR(13) NOT NULL CONSTRAINT [DF_NumberSequenceDefinition_PeriodBasis] DEFAULT 'CALENDAR_YEAR',
    [GapPolicy] VARCHAR(10) NOT NULL CONSTRAINT [DF_NumberSequenceDefinition_GapPolicy] DEFAULT 'GAP_FREE',
    [MinWidth] INT NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_NumberSequenceDefinition_IsActive] DEFAULT 1,
    [SeedKey] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_NumberSequenceDefinition_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_NumberSequenceDefinition] PRIMARY KEY CLUSTERED ([NumberSequenceDefinitionId]),
    CONSTRAINT [UQ_NumberSequenceDefinition_Tenant] UNIQUE ([TenantId], [NumberSequenceDefinitionId]),
    CONSTRAINT [UQ_NumberSequenceDefinition_SequenceKey] UNIQUE ([TenantId], [SequenceKey]),
    CONSTRAINT [CK_NumberSequenceDefinition_1] CHECK (PeriodBasis <> 'FISCAL_YEAR' OR ScopeLevel = 'COMPANY'),
    CONSTRAINT [CK_NumberSequenceDefinition_2] CHECK (MinWidth IS NULL OR (MinWidth >= 1 AND MinWidth <= 18)),
    CONSTRAINT [CK_NumberSequenceDefinition_ScopeLevel] CHECK ([ScopeLevel] IS NULL OR [ScopeLevel] IN ('TENANT', 'COMPANY')),
    CONSTRAINT [CK_NumberSequenceDefinition_PeriodBasis] CHECK ([PeriodBasis] IS NULL OR [PeriodBasis] IN ('CALENDAR_YEAR', 'FISCAL_YEAR', 'NONE')),
    CONSTRAINT [CK_NumberSequenceDefinition_GapPolicy] CHECK ([GapPolicy] IS NULL OR [GapPolicy] IN ('GAP_FREE', 'ALLOW_GAPS'))
);
GO
-- Counter per (definition, optional company, period); its row is locked on allocation inside the caller's transaction (BR-PLT-010)
CREATE TABLE [cfg].[NumberSequence] (
    [TenantId] INT NOT NULL,
    [NumberSequenceId] BIGINT IDENTITY(1,1) NOT NULL,
    [DefinitionId] BIGINT NOT NULL,
    [CompanyId] BIGINT NULL,
    [PeriodKey] VARCHAR(10) NOT NULL,
    [NextValue] BIGINT NOT NULL CONSTRAINT [DF_NumberSequence_NextValue] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_NumberSequence_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_NumberSequence] PRIMARY KEY CLUSTERED ([NumberSequenceId]),
    CONSTRAINT [UQ_NumberSequence_Tenant] UNIQUE ([TenantId], [NumberSequenceId]),
    CONSTRAINT [CK_NumberSequence_1] CHECK (NextValue >= 1)
);
GO
-- Issued document numbers; a cancelled number is never reused (FR-PLT-026, BR-PLT-010)
CREATE TABLE [cfg].[NumberIssue] (
    [TenantId] INT NOT NULL,
    [NumberIssueId] BIGINT IDENTITY(1,1) NOT NULL,
    [SequenceId] BIGINT NOT NULL,
    [SeqValue] BIGINT NOT NULL,
    [IssuedNumber] NVARCHAR(60) NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_NumberIssue_Status] DEFAULT 'ISSUED',
    [VoidReason] NVARCHAR(MAX) NULL,
    [VoidedAt] DATETIME2(3) NULL,
    [VoidedBy] BIGINT NULL,
    [EntityType] VARCHAR(60) NULL,
    [EntityId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_NumberIssue_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_NumberIssue] PRIMARY KEY CLUSTERED ([NumberIssueId]),
    CONSTRAINT [UQ_NumberIssue_Tenant] UNIQUE ([TenantId], [NumberIssueId]),
    CONSTRAINT [UQ_NumberIssue_SequenceId_SeqValue] UNIQUE ([TenantId], [SequenceId], [SeqValue]),
    CONSTRAINT [UQ_NumberIssue_SequenceId_IssuedNumber] UNIQUE ([TenantId], [SequenceId], [IssuedNumber]),
    CONSTRAINT [CK_NumberIssue_1] CHECK ((Status = 'ISSUED' AND VoidReason IS NULL AND VoidedAt IS NULL) OR (Status = 'VOID' AND VoidReason IS NOT NULL AND VoidedAt IS NOT NULL)),
    CONSTRAINT [CK_NumberIssue_2] CHECK ((EntityType IS NULL AND EntityId IS NULL) OR (EntityType IS NOT NULL AND EntityId IS NOT NULL)),
    CONSTRAINT [CK_NumberIssue_Status] CHECK ([Status] IS NULL OR [Status] IN ('ISSUED', 'VOID'))
);
GO
-- Expiry alert rule per item type (FR-PLT-038, BR-PLT-013)
CREATE TABLE [cfg].[ExpiryAlertRule] (
    [TenantId] INT NOT NULL,
    [ExpiryAlertRuleId] BIGINT IDENTITY(1,1) NOT NULL,
    [ItemType] VARCHAR(60) NOT NULL,
    [LeadDays] NVARCHAR(MAX) NOT NULL,
    [ScopeByCompany] BIT NOT NULL CONSTRAINT [DF_ExpiryAlertRule_ScopeByCompany] DEFAULT 1,
    [ReminderAfterExpiryDays] INT NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_ExpiryAlertRule_IsActive] DEFAULT 1,
    [SeedKey] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ExpiryAlertRule_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ExpiryAlertRule] PRIMARY KEY CLUSTERED ([ExpiryAlertRuleId]),
    CONSTRAINT [UQ_ExpiryAlertRule_Tenant] UNIQUE ([TenantId], [ExpiryAlertRuleId]),
    CONSTRAINT [UQ_ExpiryAlertRule_ItemType] UNIQUE ([TenantId], [ItemType]),
    CONSTRAINT [CK_ExpiryAlertRule_1] CHECK (ReminderAfterExpiryDays IS NULL OR ReminderAfterExpiryDays > 0),
    CONSTRAINT [CK_ExpiryAlertRule_LeadDays_json] CHECK ([LeadDays] IS NULL OR ISJSON([LeadDays], VALUE) = 1)
);
GO
-- Roles that receive an alert rule's alerts, within the company scope; replaces the RecipientRoles code list, so a renamed or missing role cannot silently receive nothing (FR-PLT-038, DR-16)
CREATE TABLE [cfg].[ExpiryAlertRuleRole] (
    [TenantId] INT NOT NULL,
    [ExpiryAlertRuleId] BIGINT NOT NULL,
    [RoleId] BIGINT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ExpiryAlertRuleRole_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_ExpiryAlertRuleRole] PRIMARY KEY CLUSTERED ([TenantId], [ExpiryAlertRuleId], [RoleId])
);
GO
-- Log of sent expiry alerts: one event per (item, threshold), never repeated on the same day (FR-PLT-038)
CREATE TABLE [cfg].[ExpiryAlertLog] (
    [TenantId] INT NOT NULL,
    [ExpiryAlertLogId] BIGINT IDENTITY(1,1) NOT NULL,
    [ExpiryAlertRuleId] BIGINT NOT NULL,
    [ItemId] BIGINT NOT NULL,
    [ExpiryDate] DATE NOT NULL,
    [AlertKind] VARCHAR(10) NOT NULL,
    [Threshold] INT NOT NULL CONSTRAINT [DF_ExpiryAlertLog_Threshold] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ExpiryAlertLog_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_ExpiryAlertLog] PRIMARY KEY CLUSTERED ([ExpiryAlertLogId]),
    CONSTRAINT [UQ_ExpiryAlertLog_Tenant] UNIQUE ([TenantId], [ExpiryAlertLogId]),
    CONSTRAINT [UQ_ExpiryAlertLog_ExpiryAlertRuleId_ItemId_ExpiryDate_AlertKind_Threshold] UNIQUE ([TenantId], [ExpiryAlertRuleId], [ItemId], [ExpiryDate], [AlertKind], [Threshold]),
    CONSTRAINT [CK_ExpiryAlertLog_AlertKind] CHECK ([AlertKind] IS NULL OR [AlertKind] IN ('LEAD', 'EXPIRED', 'REMINDER'))
);
GO
-- Tenant data export request (FR-PLT-039, BR-PLT-016)
CREATE TABLE [cfg].[DataExportJob] (
    [TenantId] INT NOT NULL,
    [DataExportJobId] BIGINT IDENTITY(1,1) NOT NULL,
    [RequestedBy] BIGINT NOT NULL,
    [RequestedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_DataExportJob_RequestedAt] DEFAULT SYSUTCDATETIME(),
    [Scope] VARCHAR(10) NOT NULL CONSTRAINT [DF_DataExportJob_Scope] DEFAULT 'FULL',
    [ScopeDetailJson] NVARCHAR(MAX) NULL,
    [IncludesRestricted] BIT NOT NULL CONSTRAINT [DF_DataExportJob_IncludesRestricted] DEFAULT 0,
    [ApprovedBy] BIGINT NULL,
    [ApprovedAt] DATETIME2(3) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_DataExportJob_Status] DEFAULT 'REQUESTED',
    [StartedAt] DATETIME2(3) NULL,
    [FinishedAt] DATETIME2(3) NULL,
    [ExpiresAt] DATETIME2(3) NULL,
    [PackageDocumentId] BIGINT NULL,
    [PackageSha256] VARBINARY(32) NULL,
    [FailureReason] NVARCHAR(500) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_DataExportJob_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_DataExportJob_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_DataExportJob] PRIMARY KEY CLUSTERED ([DataExportJobId]),
    CONSTRAINT [UQ_DataExportJob_Tenant] UNIQUE ([TenantId], [DataExportJobId]),
    CONSTRAINT [UQ_DataExportJob_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_DataExportJob_1] CHECK (IncludesRestricted = 0 OR Status = 'REQUESTED' OR ApprovedBy IS NOT NULL),
    CONSTRAINT [CK_DataExportJob_2] CHECK ((ApprovedBy IS NULL AND ApprovedAt IS NULL) OR (ApprovedBy IS NOT NULL AND ApprovedAt IS NOT NULL)),
    CONSTRAINT [CK_DataExportJob_3] CHECK (Status NOT IN ('READY','EXPIRED') OR ExpiresAt IS NOT NULL),
    CONSTRAINT [CK_DataExportJob_4] CHECK (Status <> 'READY' OR (PackageDocumentId IS NOT NULL AND PackageSha256 IS NOT NULL)),
    CONSTRAINT [CK_DataExportJob_5] CHECK (FinishedAt IS NULL OR StartedAt IS NULL OR FinishedAt >= StartedAt),
    CONSTRAINT [CK_DataExportJob_Scope] CHECK ([Scope] IS NULL OR [Scope] IN ('FULL', 'PARTIAL')),
    CONSTRAINT [CK_DataExportJob_Status] CHECK ([Status] IS NULL OR [Status] IN ('REQUESTED', 'APPROVED', 'RUNNING', 'READY', 'EXPIRED', 'FAILED')),
    CONSTRAINT [CK_DataExportJob_ScopeDetailJson_json] CHECK ([ScopeDetailJson] IS NULL OR ISJSON([ScopeDetailJson], VALUE) = 1)
);
GO
-- Non-working day; NULL TenantId = platform holiday, read-only (FR-PLT-035, BR-PLT-014)
CREATE TABLE [cfg].[NonWorkingDay] (
    [TenantId] INT NULL,
    [NonWorkingDayId] BIGINT IDENTITY(1,1) NOT NULL,
    [CountryId] INT NOT NULL,
    [OnDate] DATE NOT NULL,
    [NameAr] NVARCHAR(200) NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Kind] VARCHAR(10) NOT NULL CONSTRAINT [DF_NonWorkingDay_Kind] DEFAULT 'HOLIDAY',
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_NonWorkingDay_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_NonWorkingDay] PRIMARY KEY CLUSTERED ([NonWorkingDayId]),
    CONSTRAINT [UQ_NonWorkingDay_Tenant] UNIQUE ([TenantId], [NonWorkingDayId]),
    CONSTRAINT [UQ_NonWorkingDay_CountryId_OnDate] UNIQUE ([TenantId], [CountryId], [OnDate]),
    CONSTRAINT [CK_NonWorkingDay_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('HOLIDAY', 'BRIDGE', 'OTHER'))
);
GO
-- Outbound queue with at-least-once delivery; the payload carries identifiers without restricted data; only DELIVERED events may be deleted (043, FR-PLT-042, DR-14)
CREATE TABLE [cfg].[OutboxEvent] (
    [TenantId] INT NOT NULL,
    [OutboxEventId] BIGINT IDENTITY(1,1) NOT NULL,
    [MessageId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_OutboxEvent_MessageId] DEFAULT NEWID(),
    [EventName] VARCHAR(100) NOT NULL,
    [AggregateType] VARCHAR(60) NULL,
    [AggregateId] BIGINT NULL,
    [PayloadJson] NVARCHAR(MAX) NOT NULL,
    [OccurredAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_OutboxEvent_OccurredAt] DEFAULT SYSUTCDATETIME(),
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_OutboxEvent_Status] DEFAULT 'PENDING',
    [AttemptCount] INT NOT NULL CONSTRAINT [DF_OutboxEvent_AttemptCount] DEFAULT 0,
    [NextAttemptAt] DATETIME2(3) NULL,
    [LockedBy] VARCHAR(60) NULL,
    [LockedUntil] DATETIME2(3) NULL,
    [DeliveredAt] DATETIME2(3) NULL,
    [LastError] NVARCHAR(1000) NULL,
    [CorrelationId] UNIQUEIDENTIFIER NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_OutboxEvent_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_OutboxEvent] PRIMARY KEY CLUSTERED ([OutboxEventId]),
    CONSTRAINT [UQ_OutboxEvent_Tenant] UNIQUE ([TenantId], [OutboxEventId]),
    CONSTRAINT [UQ_OutboxEvent_MessageId] UNIQUE ([TenantId], [MessageId]),
    CONSTRAINT [CK_OutboxEvent_1] CHECK (AttemptCount >= 0),
    CONSTRAINT [CK_OutboxEvent_2] CHECK (EventName LIKE '%.%'),
    CONSTRAINT [CK_OutboxEvent_3] CHECK (Status <> 'PROCESSING' OR (LockedBy IS NOT NULL AND LockedUntil IS NOT NULL)),
    CONSTRAINT [CK_OutboxEvent_4] CHECK (Status <> 'DELIVERED' OR DeliveredAt IS NOT NULL),
    CONSTRAINT [CK_OutboxEvent_5] CHECK (Status <> 'DEAD' OR LastError IS NOT NULL),
    CONSTRAINT [CK_OutboxEvent_Status] CHECK ([Status] IS NULL OR [Status] IN ('PENDING', 'PROCESSING', 'DELIVERED', 'FAILED', 'DEAD')),
    CONSTRAINT [CK_OutboxEvent_PayloadJson_json] CHECK ([PayloadJson] IS NULL OR ISJSON([PayloadJson], VALUE) = 1)
);
GO
-- Background job catalogue: the only JobKey values a job connection may bind with (FR-PLT-044)
CREATE TABLE [cfg].[JobDefinition] (
    [JobDefinitionId] INT IDENTITY(1,1) NOT NULL,
    [JobKey] VARCHAR(80) NOT NULL,
    [Scope] VARCHAR(10) NOT NULL,
    [RunsInStatuses] VARCHAR(49) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_JobDefinition_IsActive] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_JobDefinition_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_JobDefinition] PRIMARY KEY CLUSTERED ([JobDefinitionId]),
    CONSTRAINT [UQ_JobDefinition_JobKey] UNIQUE ([JobKey]),
    CONSTRAINT [CK_JobDefinition_1] CHECK (Scope = 'PLATFORM' OR RunsInStatuses IS NOT NULL),
    CONSTRAINT [CK_JobDefinition_Scope] CHECK ([Scope] IS NULL OR [Scope] IN ('TENANT', 'PLATFORM')),
    CONSTRAINT [CK_JobDefinition_RunsInStatuses] CHECK ([RunsInStatuses] IS NULL OR LEN([RunsInStatuses]) + 1 = CASE WHEN CHARINDEX(',TRIAL,', (',' + [RunsInStatuses] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 6 ELSE 0 END + CASE WHEN CHARINDEX(',ACTIVE,', (',' + [RunsInStatuses] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 7 ELSE 0 END + CASE WHEN CHARINDEX(',SUSPENDED,', (',' + [RunsInStatuses] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 10 ELSE 0 END + CASE WHEN CHARINDEX(',CLOSED,', (',' + [RunsInStatuses] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 7 ELSE 0 END + CASE WHEN CHARINDEX(',ARCHIVED_READ_ONLY,', (',' + [RunsInStatuses] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 19 ELSE 0 END)
);
GO
-- Background job run log: last run, duration and result, visible to the account administrator (FR-PLT-044)
CREATE TABLE [cfg].[JobRun] (
    [TenantId] INT NOT NULL,
    [JobRunId] BIGINT IDENTITY(1,1) NOT NULL,
    [JobKey] VARCHAR(80) NOT NULL,
    [TriggerKind] VARCHAR(10) NOT NULL CONSTRAINT [DF_JobRun_TriggerKind] DEFAULT 'SCHEDULED',
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_JobRun_Status] DEFAULT 'RUNNING',
    [AttemptNo] INT NOT NULL CONSTRAINT [DF_JobRun_AttemptNo] DEFAULT 1,
    [StartedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_JobRun_StartedAt] DEFAULT SYSUTCDATETIME(),
    [FinishedAt] DATETIME2(3) NULL,
    [DurationMs] INT NULL,
    [NextRetryAt] DATETIME2(3) NULL,
    [ResultSummary] NVARCHAR(1000) NULL,
    [ErrorMessage] NVARCHAR(2000) NULL,
    [DetailJson] NVARCHAR(MAX) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_JobRun_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_JobRun] PRIMARY KEY CLUSTERED ([JobRunId]),
    CONSTRAINT [UQ_JobRun_Tenant] UNIQUE ([TenantId], [JobRunId]),
    CONSTRAINT [CK_JobRun_1] CHECK (AttemptNo >= 1),
    CONSTRAINT [CK_JobRun_2] CHECK (FinishedAt IS NULL OR FinishedAt >= StartedAt),
    CONSTRAINT [CK_JobRun_3] CHECK ((Status = 'RUNNING' AND FinishedAt IS NULL) OR (Status <> 'RUNNING' AND FinishedAt IS NOT NULL)),
    CONSTRAINT [CK_JobRun_TriggerKind] CHECK ([TriggerKind] IS NULL OR [TriggerKind] IN ('SCHEDULED', 'MANUAL', 'RETRY')),
    CONSTRAINT [CK_JobRun_Status] CHECK ([Status] IS NULL OR [Status] IN ('RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED')),
    CONSTRAINT [CK_JobRun_DetailJson_json] CHECK ([DetailJson] IS NULL OR ISJSON([DetailJson], VALUE) = 1)
);
GO
-- Numbered seed-run log per package; re-running a seed adds nothing (FR-PLT-008)
CREATE TABLE [cfg].[SeedRun] (
    [TenantId] INT NOT NULL,
    [SeedRunId] BIGINT IDENTITY(1,1) NOT NULL,
    [PackKey] VARCHAR(80) NOT NULL,
    [SeedVersion] INT NOT NULL,
    [RunKind] VARCHAR(10) NOT NULL,
    [Status] VARCHAR(10) NOT NULL,
    [CreatedCount] INT NOT NULL CONSTRAINT [DF_SeedRun_CreatedCount] DEFAULT 0,
    [UpdatedCount] INT NOT NULL CONSTRAINT [DF_SeedRun_UpdatedCount] DEFAULT 0,
    [SkippedModifiedCount] INT NOT NULL CONSTRAINT [DF_SeedRun_SkippedModifiedCount] DEFAULT 0,
    [DiffJson] NVARCHAR(MAX) NULL,
    [StartedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SeedRun_StartedAt] DEFAULT SYSUTCDATETIME(),
    [FinishedAt] DATETIME2(3) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SeedRun_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_SeedRun] PRIMARY KEY CLUSTERED ([SeedRunId]),
    CONSTRAINT [UQ_SeedRun_Tenant] UNIQUE ([TenantId], [SeedRunId]),
    CONSTRAINT [CK_SeedRun_1] CHECK (SeedVersion >= 1),
    CONSTRAINT [CK_SeedRun_RunKind] CHECK ([RunKind] IS NULL OR [RunKind] IN ('INITIAL', 'UPGRADE', 'RERUN')),
    CONSTRAINT [CK_SeedRun_Status] CHECK ([Status] IS NULL OR [Status] IN ('SUCCEEDED', 'PARTIAL', 'FAILED')),
    CONSTRAINT [CK_SeedRun_DiffJson_json] CHECK ([DiffJson] IS NULL OR ISJSON([DiffJson], VALUE) = 1)
);
GO

-- ===== schema org =====
-- Company: root of the corporate structure (FR-ORG-001..010, BR-ORG-001..004)
CREATE TABLE [org].[Company] (
    [TenantId] INT NOT NULL,
    [CompanyId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyCode] VARCHAR(20) NOT NULL,
    [RefCode] VARCHAR(3) NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [PartyKind] VARCHAR(12) NOT NULL CONSTRAINT [DF_Company_PartyKind] DEFAULT 'ORGANIZATION',
    [PartyId] BIGINT NOT NULL,
    [LegalEntityTypeId] INT NOT NULL,
    [IsHolding] BIT NOT NULL CONSTRAINT [DF_Company_IsHolding] DEFAULT 0,
    [ParentCompanyId] BIGINT NULL,
    [CountryId] INT NOT NULL,
    [IndustryId] INT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_Company_Status] DEFAULT 'ACTIVE',
    [EstablishedOn] DATE NULL,
    [CrNumber] VARCHAR(30) NULL,
    [CrDate] DATE NULL,
    [CrDateHijriText] NVARCHAR(20) NULL,
    [ErpCompanyCode] NVARCHAR(20) NULL,
    [ErpCodeNormalized] AS (CAST(UPPER(REPLACE(ErpCompanyCode, N' ', N'')) AS NVARCHAR(20))) PERSISTED,
    [FiscalYearEndMonth] TINYINT NOT NULL,
    [FiscalYearEndDay] TINYINT NULL,
    [BaseCurrencyId] INT NULL,
    [OwnershipStatus] VARCHAR(12) NOT NULL CONSTRAINT [DF_Company_OwnershipStatus] DEFAULT 'UNDOCUMENTED',
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Company_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Company_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Company] PRIMARY KEY CLUSTERED ([CompanyId]),
    CONSTRAINT [UQ_Company_Tenant] UNIQUE ([TenantId], [CompanyId]),
    CONSTRAINT [UQ_Company_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Company_CompanyCode] UNIQUE ([TenantId], [CompanyCode]),
    CONSTRAINT [UQ_Company_PartyId] UNIQUE ([TenantId], [PartyId]),
    CONSTRAINT [CK_Company_1] CHECK (FiscalYearEndMonth BETWEEN 1 AND 12),
    CONSTRAINT [CK_Company_2] CHECK (RefCode IS NULL OR RefCode COLLATE Arabic_100_BIN2 LIKE '[A-Z][A-Z0-9]' OR RefCode COLLATE Arabic_100_BIN2 LIKE '[A-Z][A-Z0-9][A-Z0-9]'),
    CONSTRAINT [CK_Company_3] CHECK (FiscalYearEndDay IS NULL OR FiscalYearEndDay BETWEEN 1 AND 31),
    CONSTRAINT [CK_Company_4] CHECK (ParentCompanyId IS NULL OR ParentCompanyId <> CompanyId),
    CONSTRAINT [CK_Company_5] CHECK (ErpCompanyCode IS NULL OR LEN(ErpCompanyCode) > 0),
    CONSTRAINT [CK_Company_PartyKind] CHECK ([PartyKind] IS NULL OR [PartyKind] IN ('ORGANIZATION')),
    CONSTRAINT [CK_Company_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'DORMANT', 'LIQUIDATED', 'ARCHIVED')),
    CONSTRAINT [CK_Company_OwnershipStatus] CHECK ([OwnershipStatus] IS NULL OR [OwnershipStatus] IN ('COMPLETE', 'UNDOCUMENTED'))
);
GO
-- Tax rate with an effective date; NULL CompanyId = tenant default (FR-ORG-007, BR-ORG-005)
CREATE TABLE [org].[CompanyTaxRate] (
    [TenantId] INT NOT NULL,
    [CompanyTaxRateId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NULL,
    [TaxCode] VARCHAR(20) NOT NULL,
    [RatePercent] DECIMAL(9,6) NOT NULL,
    [EffectiveFrom] DATE NOT NULL,
    [EffectiveTo] DATE NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CompanyTaxRate_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CompanyTaxRate] PRIMARY KEY CLUSTERED ([CompanyTaxRateId]),
    CONSTRAINT [UQ_CompanyTaxRate_Tenant] UNIQUE ([TenantId], [CompanyTaxRateId]),
    CONSTRAINT [UQ_CompanyTaxRate_CompanyId_TaxCode_EffectiveFrom] UNIQUE ([TenantId], [CompanyId], [TaxCode], [EffectiveFrom]),
    CONSTRAINT [CK_CompanyTaxRate_1] CHECK (RatePercent >= 0 AND RatePercent <= 100),
    CONSTRAINT [CK_CompanyTaxRate_2] CHECK (EffectiveTo IS NULL OR EffectiveTo >= EffectiveFrom)
);
GO
-- Department (FR-ORG-014, BR-ORG-016, Q-ORG-09): at tenant level, optionally per company
CREATE TABLE [org].[Department] (
    [TenantId] INT NOT NULL,
    [DepartmentId] BIGINT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(20) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [Function] VARCHAR(11) NOT NULL,
    [IsTreasury] BIT NOT NULL CONSTRAINT [DF_Department_IsTreasury] DEFAULT 0,
    [CompanyId] BIGINT NULL,
    [ParentDepartmentId] BIGINT NULL,
    [HeadUserId] BIGINT NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Department_IsActive] DEFAULT 1,
    [SeedKey] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Department_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Department] PRIMARY KEY CLUSTERED ([DepartmentId]),
    CONSTRAINT [UQ_Department_Tenant] UNIQUE ([TenantId], [DepartmentId]),
    CONSTRAINT [UQ_Department_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_Department_1] CHECK (ParentDepartmentId IS NULL OR ParentDepartmentId <> DepartmentId),
    CONSTRAINT [CK_Department_Function] CHECK ([Function] IS NULL OR [Function] IN ('PROCUREMENT', 'SALES', 'TREASURY', 'FINANCE', 'OTHER'))
);
GO
-- Ownership interest with an effective date; the owner is a Party, an individual or an entity (FR-ORG-015..018, BR-ORG-006..008, G-7)
CREATE TABLE [org].[Shareholding] (
    [TenantId] INT NOT NULL,
    [ShareholdingId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [HolderPartyId] BIGINT NOT NULL,
    [SharePercent] DECIMAL(9,6) NOT NULL,
    [SharesCount] DECIMAL(19,4) NULL,
    [NominalValue] DECIMAL(19,4) NULL,
    [CurrencyId] INT NULL,
    [Layer] TINYINT NOT NULL CONSTRAINT [DF_Shareholding_Layer] DEFAULT 1,
    [IntermediatePartyId] BIGINT NULL,
    [IsBeneficialOwner] BIT NOT NULL CONSTRAINT [DF_Shareholding_IsBeneficialOwner] DEFAULT 0,
    [EffectiveFrom] DATE NOT NULL,
    [EffectiveTo] DATE NULL,
    [SourceDocumentId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Shareholding_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Shareholding] PRIMARY KEY CLUSTERED ([ShareholdingId]),
    CONSTRAINT [UQ_Shareholding_Tenant] UNIQUE ([TenantId], [ShareholdingId]),
    CONSTRAINT [UQ_Shareholding_CompanyId_HolderPartyId_Layer_IntermediatePartyId_EffectiveFrom] UNIQUE ([TenantId], [CompanyId], [HolderPartyId], [Layer], [IntermediatePartyId], [EffectiveFrom]),
    CONSTRAINT [CK_Shareholding_1] CHECK (SharePercent > 0 AND SharePercent <= 100),
    CONSTRAINT [CK_Shareholding_2] CHECK (EffectiveTo IS NULL OR EffectiveTo >= EffectiveFrom),
    CONSTRAINT [CK_Shareholding_3] CHECK (Layer >= 1),
    CONSTRAINT [CK_Shareholding_4] CHECK ((Layer = 1 AND IntermediatePartyId IS NULL) OR (Layer >= 2 AND IntermediatePartyId IS NOT NULL)),
    CONSTRAINT [CK_Shareholding_5] CHECK (IntermediatePartyId IS NULL OR IntermediatePartyId <> HolderPartyId),
    CONSTRAINT [CK_Shareholding_6] CHECK (SharesCount IS NULL OR SharesCount > 0),
    CONSTRAINT [CK_Shareholding_7] CHECK (NominalValue IS NULL OR (NominalValue >= 0 AND CurrencyId IS NOT NULL))
);
GO
-- Governing body (FR-ORG-019, BR-ORG-009)
CREATE TABLE [org].[GoverningBody] (
    [TenantId] INT NOT NULL,
    [GoverningBodyId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [BodyType] VARCHAR(18) NOT NULL,
    [NameAr] NVARCHAR(200) NULL,
    [NameEn] NVARCHAR(200) NULL,
    [TermStart] DATE NULL,
    [TermEnd] DATE NULL,
    [QuorumRuleText] NVARCHAR(MAX) NULL,
    [DecisionRuleText] NVARCHAR(MAX) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_GoverningBody_Status] DEFAULT 'ACTIVE',
    [SourceDocumentId] BIGINT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_GoverningBody_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_GoverningBody_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_GoverningBody] PRIMARY KEY CLUSTERED ([GoverningBodyId]),
    CONSTRAINT [UQ_GoverningBody_Tenant] UNIQUE ([TenantId], [GoverningBodyId]),
    CONSTRAINT [UQ_GoverningBody_Scope_CompanyId] UNIQUE ([TenantId], [CompanyId], [GoverningBodyId]),
    CONSTRAINT [UQ_GoverningBody_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_GoverningBody_1] CHECK (TermEnd IS NULL OR TermStart IS NULL OR TermEnd >= TermStart),
    CONSTRAINT [CK_GoverningBody_BodyType] CHECK ([BodyType] IS NULL OR [BodyType] IN ('BOARD_OF_DIRECTORS', 'BOARD_OF_MANAGERS', 'MANAGEMENT', 'GENERAL_ASSEMBLY')),
    CONSTRAINT [CK_GoverningBody_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'CLOSED'))
);
GO
-- Membership of a governing body (FR-ORG-020, FR-ORG-021, BR-ORG-010)
CREATE TABLE [org].[BodyMember] (
    [TenantId] INT NOT NULL,
    [BodyMemberId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [BodyId] BIGINT NOT NULL,
    [PartyId] BIGINT NOT NULL,
    [PositionId] INT NOT NULL,
    [TermStart] DATE NOT NULL,
    [TermEnd] DATE NULL,
    [RepresentedPartyId] BIGINT NULL,
    [ResignedOn] DATE NULL,
    [AppointmentDocumentId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_BodyMember_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_BodyMember] PRIMARY KEY CLUSTERED ([BodyMemberId]),
    CONSTRAINT [UQ_BodyMember_Tenant] UNIQUE ([TenantId], [BodyMemberId]),
    CONSTRAINT [UQ_BodyMember_Scope_CompanyId] UNIQUE ([TenantId], [CompanyId], [BodyMemberId]),
    CONSTRAINT [UQ_BodyMember_BodyId_PartyId_PositionId_TermStart] UNIQUE ([TenantId], [BodyId], [PartyId], [PositionId], [TermStart]),
    CONSTRAINT [CK_BodyMember_1] CHECK (TermEnd IS NULL OR TermEnd >= TermStart),
    CONSTRAINT [CK_BodyMember_2] CHECK (ResignedOn IS NULL OR ResignedOn >= TermStart),
    CONSTRAINT [CK_BodyMember_3] CHECK (RepresentedPartyId IS NULL OR RepresentedPartyId <> PartyId)
);
GO
-- Authority grant to a company (FR-ORG-023..028, BR-ORG-011..014)
CREATE TABLE [org].[AuthorityGrant] (
    [TenantId] INT NOT NULL,
    [AuthorityGrantId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [GranteeKind] VARCHAR(11) NOT NULL,
    [BodyId] BIGINT NULL,
    [BodyMemberId] BIGINT NULL,
    [PartyId] BIGINT NULL,
    [PowerTypeId] INT NOT NULL,
    [InstitutionId] BIGINT NULL,
    [CeilingAmount] DECIMAL(19,4) NULL,
    [CeilingCurrencyId] INT NULL,
    [RequiresJoint] BIT NOT NULL CONSTRAINT [DF_AuthorityGrant_RequiresJoint] DEFAULT 0,
    [JointMinSignatories] INT NULL,
    [JointNote] NVARCHAR(MAX) NULL,
    [ValidFrom] DATE NOT NULL,
    [ValidFromHijriText] NVARCHAR(20) NULL,
    [ValidTo] DATE NULL,
    [Status] VARCHAR(16) NOT NULL CONSTRAINT [DF_AuthorityGrant_Status] DEFAULT 'DRAFT',
    [ApprovedBy] BIGINT NULL,
    [ApprovedAt] DATETIME2(3) NULL,
    [RevokedAt] DATETIME2(3) NULL,
    [RevokedReason] NVARCHAR(MAX) NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ExceptionReason] NVARCHAR(500) NULL,
    [SupersedesGrantId] BIGINT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_AuthorityGrant_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_AuthorityGrant_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_AuthorityGrant] PRIMARY KEY CLUSTERED ([AuthorityGrantId]),
    CONSTRAINT [UQ_AuthorityGrant_Tenant] UNIQUE ([TenantId], [AuthorityGrantId]),
    CONSTRAINT [UQ_AuthorityGrant_Scope_CompanyId] UNIQUE ([TenantId], [CompanyId], [AuthorityGrantId]),
    CONSTRAINT [UQ_AuthorityGrant_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_AuthorityGrant_1] CHECK ((GranteeKind = 'BODY' AND BodyId IS NOT NULL AND BodyMemberId IS NULL AND PartyId IS NULL) OR (GranteeKind = 'BODY_MEMBER' AND BodyId IS NULL AND BodyMemberId IS NOT NULL AND PartyId IS NULL) OR (GranteeKind = 'PARTY' AND BodyId IS NULL AND BodyMemberId IS NULL AND PartyId IS NOT NULL)),
    CONSTRAINT [CK_AuthorityGrant_2] CHECK (CeilingAmount IS NULL OR CeilingAmount > 0),
    CONSTRAINT [CK_AuthorityGrant_3] CHECK ((CeilingAmount IS NULL AND CeilingCurrencyId IS NULL) OR (CeilingAmount IS NOT NULL AND CeilingCurrencyId IS NOT NULL)),
    CONSTRAINT [CK_AuthorityGrant_4] CHECK ((RequiresJoint = 1 AND JointMinSignatories IS NOT NULL AND JointMinSignatories >= 2) OR (RequiresJoint = 0 AND JointMinSignatories IS NULL)),
    CONSTRAINT [CK_AuthorityGrant_5] CHECK (ValidTo IS NULL OR ValidTo >= ValidFrom),
    CONSTRAINT [CK_AuthorityGrant_6] CHECK (Status IN ('DRAFT','PENDING_APPROVAL') OR SourceDocumentId IS NOT NULL OR ExceptionReason IS NOT NULL),
    CONSTRAINT [CK_AuthorityGrant_7] CHECK (Status <> 'REVOKED' OR (RevokedAt IS NOT NULL AND RevokedReason IS NOT NULL)),
    CONSTRAINT [CK_AuthorityGrant_8] CHECK (SupersedesGrantId IS NULL OR SupersedesGrantId <> AuthorityGrantId),
    CONSTRAINT [CK_AuthorityGrant_9] CHECK (Status IN ('DRAFT','PENDING_APPROVAL') OR (ApprovedBy IS NOT NULL AND ApprovedAt IS NOT NULL)),
    CONSTRAINT [CK_AuthorityGrant_10] CHECK ((ApprovedBy IS NULL AND ApprovedAt IS NULL) OR (ApprovedBy IS NOT NULL AND ApprovedAt IS NOT NULL)),
    CONSTRAINT [CK_AuthorityGrant_GranteeKind] CHECK ([GranteeKind] IS NULL OR [GranteeKind] IN ('BODY', 'BODY_MEMBER', 'PARTY')),
    CONSTRAINT [CK_AuthorityGrant_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'PENDING_APPROVAL', 'ACTIVE', 'SUPERSEDED', 'REVOKED'))
);
GO
-- Company profile, 1:1 (G-1)
CREATE TABLE [org].[CompanyProfile] (
    [TenantId] INT NOT NULL,
    [CompanyProfileId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [UnifiedNationalNo] VARCHAR(20) NULL,
    [ForeignInvestmentLicenseNo] VARCHAR(40) NULL,
    [ForeignInvestmentLicenseIssuedOn] DATE NULL,
    [ForeignInvestmentLicenseExpiresOn] DATE NULL,
    [GovernmentEntityId] VARCHAR(40) NULL,
    [Lei] VARCHAR(20) NULL,
    [HeadquartersCountryId] INT NULL,
    [EntityKind] VARCHAR(19) NULL,
    [NationalityClass] VARCHAR(10) NULL,
    [SectorId] INT NULL,
    [PrimaryActivityText] NVARCHAR(300) NULL,
    [ActivityNature] NVARCHAR(300) NULL,
    [ActivityDescription] NVARCHAR(MAX) NULL,
    [EmployeeBandId] INT NULL,
    [DeclaredBranchCount] INT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CompanyProfile_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CompanyProfile] PRIMARY KEY CLUSTERED ([CompanyProfileId]),
    CONSTRAINT [UQ_CompanyProfile_Tenant] UNIQUE ([TenantId], [CompanyProfileId]),
    CONSTRAINT [UQ_CompanyProfile_CompanyId] UNIQUE ([TenantId], [CompanyId]),
    CONSTRAINT [CK_CompanyProfile_1] CHECK (Lei IS NULL OR Lei LIKE '____________________'),
    CONSTRAINT [CK_CompanyProfile_2] CHECK (ForeignInvestmentLicenseExpiresOn IS NULL OR ForeignInvestmentLicenseIssuedOn IS NULL OR ForeignInvestmentLicenseExpiresOn > ForeignInvestmentLicenseIssuedOn),
    CONSTRAINT [CK_CompanyProfile_3] CHECK (DeclaredBranchCount IS NULL OR DeclaredBranchCount >= 0),
    CONSTRAINT [CK_CompanyProfile_EntityKind] CHECK ([EntityKind] IS NULL OR [EntityKind] IN ('COMPANY', 'SOLE_PROPRIETORSHIP', 'GOVERNMENT', 'OTHER')),
    CONSTRAINT [CK_CompanyProfile_NationalityClass] CHECK ([NationalityClass] IS NULL OR [NationalityClass] IN ('DOMESTIC', 'GCC', 'OTHER'))
);
GO
-- Branch, warehouse or subsidiary outside the account, held as text (G-3)
CREATE TABLE [org].[CompanyBranch] (
    [TenantId] INT NOT NULL,
    [CompanyBranchId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [BranchKind] VARCHAR(19) NOT NULL CONSTRAINT [DF_CompanyBranch_BranchKind] DEFAULT 'BRANCH',
    [NameAr] NVARCHAR(200) NULL,
    [NameEn] NVARCHAR(200) NULL,
    [CountryId] INT NULL,
    [LocationText] NVARCHAR(300) NULL,
    [CrNumber] VARCHAR(30) NULL,
    [UnifiedNationalNo] VARCHAR(20) NULL,
    [ActivityText] NVARCHAR(300) NULL,
    [OwnershipPercent] DECIMAL(9,6) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_CompanyBranch_Status] DEFAULT 'ACTIVE',
    [ClosedOn] DATE NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CompanyBranch_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CompanyBranch] PRIMARY KEY CLUSTERED ([CompanyBranchId]),
    CONSTRAINT [UQ_CompanyBranch_Tenant] UNIQUE ([TenantId], [CompanyBranchId]),
    CONSTRAINT [CK_CompanyBranch_1] CHECK (NameAr IS NOT NULL OR NameEn IS NOT NULL),
    CONSTRAINT [CK_CompanyBranch_2] CHECK (OwnershipPercent IS NULL OR (BranchKind = 'EXTERNAL_SUBSIDIARY' AND OwnershipPercent > 0 AND OwnershipPercent <= 100)),
    CONSTRAINT [CK_CompanyBranch_3] CHECK (ClosedOn IS NULL OR Status = 'CLOSED'),
    CONSTRAINT [CK_CompanyBranch_BranchKind] CHECK ([BranchKind] IS NULL OR [BranchKind] IN ('BRANCH', 'WAREHOUSE', 'EXTERNAL_SUBSIDIARY')),
    CONSTRAINT [CK_CompanyBranch_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'CLOSED'))
);
GO
-- KYC financial profile with an effective date: revenue band and purpose (G-4)
CREATE TABLE [org].[CompanyKycFinancialProfile] (
    [TenantId] INT NOT NULL,
    [CompanyKycFinancialProfileId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [EffectiveFrom] DATE NOT NULL,
    [EffectiveTo] DATE NULL,
    [RevenueBandId] INT NULL,
    [AccountPurposeText] NVARCHAR(500) NULL,
    [AccountCurrencyId] INT NULL,
    [PreferredLanguage] VARCHAR(10) NULL,
    [FundsTransferSource] NVARCHAR(300) NULL,
    [RequestedServices] NVARCHAR(300) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CompanyKycFinancialProfile_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CompanyKycFinancialProfile] PRIMARY KEY CLUSTERED ([CompanyKycFinancialProfileId]),
    CONSTRAINT [UQ_CompanyKycFinancialProfile_Tenant] UNIQUE ([TenantId], [CompanyKycFinancialProfileId]),
    CONSTRAINT [UQ_CompanyKycFinancialProfile_CompanyId_EffectiveFrom] UNIQUE ([TenantId], [CompanyId], [EffectiveFrom]),
    CONSTRAINT [CK_CompanyKycFinancialProfile_1] CHECK (EffectiveTo IS NULL OR EffectiveTo >= EffectiveFrom),
    CONSTRAINT [CK_CompanyKycFinancialProfile_PreferredLanguage] CHECK ([PreferredLanguage] IS NULL OR [PreferredLanguage] IN ('ar', 'en'))
);
GO
-- Monthly expected cash-flow matrix (CTP): direction x five items (G-4)
CREATE TABLE [org].[CompanyExpectedFlow] (
    [TenantId] INT NOT NULL,
    [CompanyExpectedFlowId] BIGINT IDENTITY(1,1) NOT NULL,
    [FinancialProfileId] BIGINT NOT NULL,
    [Direction] VARCHAR(10) NOT NULL,
    [FlowKind] VARCHAR(22) NOT NULL,
    [MonthlyAmount] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CompanyExpectedFlow_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CompanyExpectedFlow] PRIMARY KEY CLUSTERED ([CompanyExpectedFlowId]),
    CONSTRAINT [UQ_CompanyExpectedFlow_Tenant] UNIQUE ([TenantId], [CompanyExpectedFlowId]),
    CONSTRAINT [UQ_CompanyExpectedFlow_FinancialProfileId_Direction_FlowKind] UNIQUE ([TenantId], [FinancialProfileId], [Direction], [FlowKind]),
    CONSTRAINT [CK_CompanyExpectedFlow_1] CHECK (MonthlyAmount >= 0),
    CONSTRAINT [CK_CompanyExpectedFlow_Direction] CHECK ([Direction] IS NULL OR [Direction] IN ('DEPOSIT', 'WITHDRAWAL')),
    CONSTRAINT [CK_CompanyExpectedFlow_FlowKind] CHECK ([FlowKind] IS NULL OR [FlowKind] IN ('CASH', 'OTHER', 'LOCAL_TRANSFER', 'INTERNATIONAL_TRANSFER', 'CHEQUE'))
);
GO
-- Sources of funds and wealth: multiple-value list (G-4)
CREATE TABLE [org].[CompanyWealthSource] (
    [TenantId] INT NOT NULL,
    [FinancialProfileId] BIGINT NOT NULL,
    [WealthSourceId] INT NOT NULL,
    [OtherText] NVARCHAR(200) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CompanyWealthSource_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_CompanyWealthSource] PRIMARY KEY CLUSTERED ([TenantId], [FinancialProfileId], [WealthSourceId])
);
GO
-- Company disclosures (G-5)
CREATE TABLE [org].[CompanyDisclosure] (
    [TenantId] INT NOT NULL,
    [CompanyDisclosureId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [DisclosureKind] VARCHAR(23) NOT NULL,
    [Description] NVARCHAR(MAX) NOT NULL,
    [EventDate] DATE NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_CompanyDisclosure_Status] DEFAULT 'OPEN',
    [ResolvedOn] DATE NULL,
    [SourceDocumentId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CompanyDisclosure_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CompanyDisclosure] PRIMARY KEY CLUSTERED ([CompanyDisclosureId]),
    CONSTRAINT [UQ_CompanyDisclosure_Tenant] UNIQUE ([TenantId], [CompanyDisclosureId]),
    CONSTRAINT [CK_CompanyDisclosure_1] CHECK (ResolvedOn IS NULL OR Status = 'RESOLVED'),
    CONSTRAINT [CK_CompanyDisclosure_DisclosureKind] CHECK ([DisclosureKind] IS NULL OR [DisclosureKind] IN ('REGULATORY_DISCIPLINARY', 'TAX_ISSUE', 'LITIGATION', 'FACILITY_RESCHEDULING', 'CONVICTION', 'OTHER')),
    CONSTRAINT [CK_CompanyDisclosure_Status] CHECK ([Status] IS NULL OR [Status] IN ('OPEN', 'RESOLVED'))
);
GO
-- Key relations: auditors, legal counsel, regulators, and major customers and suppliers (G-6)
CREATE TABLE [org].[CompanyKeyRelation] (
    [TenantId] INT NOT NULL,
    [CompanyKeyRelationId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [RelationKind] VARCHAR(14) NOT NULL,
    [NameAr] NVARCHAR(200) NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Note] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_CompanyKeyRelation_IsActive] DEFAULT 1,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_CompanyKeyRelation_SortOrder] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CompanyKeyRelation_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CompanyKeyRelation] PRIMARY KEY CLUSTERED ([CompanyKeyRelationId]),
    CONSTRAINT [UQ_CompanyKeyRelation_Tenant] UNIQUE ([TenantId], [CompanyKeyRelationId]),
    CONSTRAINT [CK_CompanyKeyRelation_1] CHECK (NameAr IS NOT NULL OR NameEn IS NOT NULL),
    CONSTRAINT [CK_CompanyKeyRelation_RelationKind] CHECK ([RelationKind] IS NULL OR [RelationKind] IN ('AUDITOR', 'ACCOUNTANT', 'LEGAL_ADVISOR', 'REGULATOR', 'MAJOR_CUSTOMER', 'MAJOR_SUPPLIER', 'OTHER'))
);
GO

-- ===== schema pty =====
-- Person or entity; no stored role (FR-PTY-001..003, BR-PTY-001..004, BR-PTY-016..018)
CREATE TABLE [pty].[Party] (
    [TenantId] INT NOT NULL,
    [PartyId] BIGINT IDENTITY(1,1) NOT NULL,
    [PartyCode] VARCHAR(20) NOT NULL,
    [Kind] VARCHAR(12) NOT NULL,
    [NameAr] NVARCHAR(200) NULL,
    [NameEn] NVARCHAR(200) NULL,
    [NameNormalized] NVARCHAR(400) NULL,
    [CountryId] INT NULL,
    [ResidencyStatus] VARCHAR(12) NULL,
    [BirthDate] DATE NULL,
    [BirthDateHijriText] NVARCHAR(20) NULL,
    [BirthPlace] NVARCHAR(100) NULL,
    [BirthCountryId] INT NULL,
    [MaritalStatus] VARCHAR(10) NULL,
    [Gender] VARCHAR(10) NULL,
    [EducationLevelId] INT NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Party_IsActive] DEFAULT 1,
    [MergedIntoPartyId] BIGINT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Party_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Party_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Party] PRIMARY KEY CLUSTERED ([PartyId]),
    CONSTRAINT [UQ_Party_Tenant] UNIQUE ([TenantId], [PartyId]),
    CONSTRAINT [UQ_Party_Scope_Kind] UNIQUE ([TenantId], [Kind], [PartyId]),
    CONSTRAINT [UQ_Party_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Party_PartyCode] UNIQUE ([TenantId], [PartyCode]),
    CONSTRAINT [CK_Party_1] CHECK (NameAr IS NOT NULL OR NameEn IS NOT NULL),
    CONSTRAINT [CK_Party_2] CHECK (Kind = 'INDIVIDUAL' OR (ResidencyStatus IS NULL AND BirthDate IS NULL AND MaritalStatus IS NULL AND Gender IS NULL AND EducationLevelId IS NULL)),
    CONSTRAINT [CK_Party_3] CHECK (MergedIntoPartyId IS NULL OR (IsActive = 0 AND MergedIntoPartyId <> PartyId)),
    CONSTRAINT [CK_Party_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('INDIVIDUAL', 'ORGANIZATION')),
    CONSTRAINT [CK_Party_ResidencyStatus] CHECK ([ResidencyStatus] IS NULL OR [ResidencyStatus] IN ('CITIZEN', 'RESIDENT', 'NON_RESIDENT', 'UNKNOWN')),
    CONSTRAINT [CK_Party_MaritalStatus] CHECK ([MaritalStatus] IS NULL OR [MaritalStatus] IN ('SINGLE', 'MARRIED', 'DIVORCED', 'WIDOWED')),
    CONSTRAINT [CK_Party_Gender] CHECK ([Gender] IS NULL OR [Gender] IN ('MALE', 'FEMALE'))
);
GO
-- Identity document; the number is encrypted and images are restricted documents (FR-PTY-004..009, FR-PTY-020..022, BR-PTY-002..008)
CREATE TABLE [pty].[IdentityDocument] (
    [TenantId] INT NOT NULL,
    [IdentityDocumentId] BIGINT IDENTITY(1,1) NOT NULL,
    [PartyId] BIGINT NOT NULL,
    [DocKind] VARCHAR(14) NOT NULL,
    [IssuingCountryId] INT NOT NULL,
    [IssuingAuthority] NVARCHAR(200) NULL,
    [IssuePlace] NVARCHAR(100) NULL,
    [NumberEnc] VARBINARY(512) NOT NULL,
    [NumberMask] NVARCHAR(32) NOT NULL,
    [NumberHash] VARBINARY(32) NOT NULL,
    [EncKeyPurpose] VARCHAR(11) NOT NULL CONSTRAINT [DF_IdentityDocument_EncKeyPurpose] DEFAULT 'DATA',
    [EncKeyId] BIGINT NOT NULL,
    [HashKeyPurpose] VARCHAR(11) NOT NULL CONSTRAINT [DF_IdentityDocument_HashKeyPurpose] DEFAULT 'BLIND_INDEX',
    [HashKeyId] BIGINT NOT NULL,
    [IssueDate] DATE NULL,
    [IssueDateHijriText] NVARCHAR(20) NULL,
    [ExpiryDate] DATE NULL,
    [ExpiryDateHijriText] NVARCHAR(20) NULL,
    [IsPrimary] BIT NOT NULL CONSTRAINT [DF_IdentityDocument_IsPrimary] DEFAULT 0,
    [IsSuperseded] BIT NOT NULL CONSTRAINT [DF_IdentityDocument_IsSuperseded] DEFAULT 0,
    [SupersededById] BIGINT NULL,
    [VerifiedAt] DATETIME2(3) NULL,
    [VerifiedBy] BIGINT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_IdentityDocument_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_IdentityDocument_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_IdentityDocument] PRIMARY KEY CLUSTERED ([IdentityDocumentId]),
    CONSTRAINT [UQ_IdentityDocument_Tenant] UNIQUE ([TenantId], [IdentityDocumentId]),
    CONSTRAINT [UQ_IdentityDocument_Scope_PartyId] UNIQUE ([TenantId], [PartyId], [IdentityDocumentId]),
    CONSTRAINT [UQ_IdentityDocument_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_IdentityDocument_1] CHECK (ExpiryDate IS NULL OR IssueDate IS NULL OR ExpiryDate > IssueDate),
    CONSTRAINT [CK_IdentityDocument_2] CHECK (SupersededById IS NULL OR (SupersededById <> IdentityDocumentId AND IsSuperseded = 1)),
    CONSTRAINT [CK_IdentityDocument_3] CHECK (DATALENGTH(NumberEnc) >= 29),
    CONSTRAINT [CK_IdentityDocument_4] CHECK (IsSuperseded = 0 OR IsPrimary = 0),
    CONSTRAINT [CK_IdentityDocument_5] CHECK (VerifiedBy IS NULL OR VerifiedAt IS NOT NULL),
    CONSTRAINT [CK_IdentityDocument_DocKind] CHECK ([DocKind] IS NULL OR [DocKind] IN ('NATIONAL_ID', 'RESIDENCE', 'PASSPORT', 'GCC_ID', 'COMMERCIAL_REG', 'OTHER_ORG')),
    CONSTRAINT [CK_IdentityDocument_EncKeyPurpose] CHECK ([EncKeyPurpose] IS NULL OR [EncKeyPurpose] IN ('DATA')),
    CONSTRAINT [CK_IdentityDocument_HashKeyPurpose] CHECK ([HashKeyPurpose] IS NULL OR [HashKeyPurpose] IN ('BLIND_INDEX'))
);
GO
-- Postal address with an exclusive owner arc: exactly one of Party, Institution, Unit or Contact (FR-PTY-011, BR-PTY-015)
CREATE TABLE [pty].[Address] (
    [TenantId] INT NOT NULL,
    [AddressId] BIGINT IDENTITY(1,1) NOT NULL,
    [PartyId] BIGINT NULL,
    [InstitutionId] BIGINT NULL,
    [UnitId] BIGINT NULL,
    [ContactId] BIGINT NULL,
    [AddressType] VARCHAR(11) NOT NULL,
    [IsPrimary] BIT NOT NULL CONSTRAINT [DF_Address_IsPrimary] DEFAULT 0,
    [IsCurrent] BIT NOT NULL CONSTRAINT [DF_Address_IsCurrent] DEFAULT 1,
    [CountryId] INT NOT NULL,
    [Region] NVARCHAR(100) NULL,
    [City] NVARCHAR(100) NULL,
    [District] NVARCHAR(100) NULL,
    [Street] NVARCHAR(150) NULL,
    [BuildingNumber] NVARCHAR(20) NULL,
    [UnitNumber] NVARCHAR(20) NULL,
    [PostalCode] NVARCHAR(20) NULL,
    [AdditionalNumber] NVARCHAR(20) NULL,
    [ShortCode] NVARCHAR(20) NULL,
    [PoBoxNumber] NVARCHAR(30) NULL,
    [FreeText] NVARCHAR(500) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Address_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Address] PRIMARY KEY CLUSTERED ([AddressId]),
    CONSTRAINT [UQ_Address_Tenant] UNIQUE ([TenantId], [AddressId]),
    CONSTRAINT [CK_Address_1] CHECK ((PartyId IS NOT NULL AND InstitutionId IS NULL AND UnitId IS NULL AND ContactId IS NULL) OR (PartyId IS NULL AND InstitutionId IS NOT NULL AND UnitId IS NULL AND ContactId IS NULL) OR (PartyId IS NULL AND InstitutionId IS NULL AND UnitId IS NOT NULL AND ContactId IS NULL) OR (PartyId IS NULL AND InstitutionId IS NULL AND UnitId IS NULL AND ContactId IS NOT NULL)),
    CONSTRAINT [CK_Address_2] CHECK (IsPrimary = 0 OR IsCurrent = 1),
    CONSTRAINT [CK_Address_3] CHECK (AddressType <> 'PO_BOX' OR PoBoxNumber IS NOT NULL),
    CONSTRAINT [CK_Address_AddressType] CHECK ([AddressType] IS NULL OR [AddressType] IN ('NATIONAL', 'RESIDENTIAL', 'WORK', 'PO_BOX', 'REGISTERED', 'OTHER'))
);
GO
-- Contact method (phone, e-mail and similar) with an exclusive owner arc, as for addresses (FR-PTY-012, BR-PTY-015)
CREATE TABLE [pty].[ContactMethod] (
    [TenantId] INT NOT NULL,
    [ContactMethodId] BIGINT IDENTITY(1,1) NOT NULL,
    [PartyId] BIGINT NULL,
    [InstitutionId] BIGINT NULL,
    [UnitId] BIGINT NULL,
    [ContactId] BIGINT NULL,
    [Kind] VARCHAR(10) NOT NULL,
    [Value] NVARCHAR(200) NOT NULL,
    [NormalizedValue] NVARCHAR(200) NOT NULL,
    [Label] NVARCHAR(100) NULL,
    [IsPrimary] BIT NOT NULL CONSTRAINT [DF_ContactMethod_IsPrimary] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ContactMethod_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ContactMethod] PRIMARY KEY CLUSTERED ([ContactMethodId]),
    CONSTRAINT [UQ_ContactMethod_Tenant] UNIQUE ([TenantId], [ContactMethodId]),
    CONSTRAINT [CK_ContactMethod_1] CHECK ((PartyId IS NOT NULL AND InstitutionId IS NULL AND UnitId IS NULL AND ContactId IS NULL) OR (PartyId IS NULL AND InstitutionId IS NOT NULL AND UnitId IS NULL AND ContactId IS NULL) OR (PartyId IS NULL AND InstitutionId IS NULL AND UnitId IS NOT NULL AND ContactId IS NULL) OR (PartyId IS NULL AND InstitutionId IS NULL AND UnitId IS NULL AND ContactId IS NOT NULL)),
    CONSTRAINT [CK_ContactMethod_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('MOBILE', 'PHONE', 'EMAIL', 'FAX', 'WEBSITE', 'OTHER'))
);
GO
-- Custom field definition (FR-PTY-013, BR-PTY-014)
CREATE TABLE [pty].[CustomFieldDefinition] (
    [TenantId] INT NOT NULL,
    [CustomFieldDefinitionId] BIGINT IDENTITY(1,1) NOT NULL,
    [FieldKey] VARCHAR(60) NOT NULL,
    [LabelAr] NVARCHAR(200) NOT NULL,
    [LabelEn] NVARCHAR(200) NOT NULL,
    [DataType] VARCHAR(10) NOT NULL,
    [ListValues] NVARCHAR(MAX) NULL,
    [Sensitivity] VARCHAR(12) NOT NULL CONSTRAINT [DF_CustomFieldDefinition_Sensitivity] DEFAULT 'CONFIDENTIAL',
    [InstitutionId] BIGINT NULL,
    [AppliesToKind] VARCHAR(12) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_CustomFieldDefinition_IsActive] DEFAULT 1,
    [SeedKey] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CustomFieldDefinition_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CustomFieldDefinition] PRIMARY KEY CLUSTERED ([CustomFieldDefinitionId]),
    CONSTRAINT [UQ_CustomFieldDefinition_Tenant] UNIQUE ([TenantId], [CustomFieldDefinitionId]),
    CONSTRAINT [UQ_CustomFieldDefinition_FieldKey] UNIQUE ([TenantId], [FieldKey]),
    CONSTRAINT [CK_CustomFieldDefinition_1] CHECK ((DataType = 'LIST' AND ListValues IS NOT NULL) OR (DataType <> 'LIST' AND ListValues IS NULL)),
    CONSTRAINT [CK_CustomFieldDefinition_DataType] CHECK ([DataType] IS NULL OR [DataType] IN ('TEXT', 'NUMBER', 'DATE', 'LIST', 'BOOLEAN', 'AMOUNT')),
    CONSTRAINT [CK_CustomFieldDefinition_Sensitivity] CHECK ([Sensitivity] IS NULL OR [Sensitivity] IN ('CONFIDENTIAL', 'RESTRICTED')),
    CONSTRAINT [CK_CustomFieldDefinition_AppliesToKind] CHECK ([AppliesToKind] IS NULL OR [AppliesToKind] IN ('INDIVIDUAL', 'ORGANIZATION')),
    CONSTRAINT [CK_CustomFieldDefinition_ListValues_json] CHECK ([ListValues] IS NULL OR ISJSON([ListValues], VALUE) = 1)
);
GO
-- Custom-field value for a party (FR-PTY-013, FR-PTY-014)
CREATE TABLE [pty].[PartyCustomField] (
    [TenantId] INT NOT NULL,
    [PartyCustomFieldId] BIGINT IDENTITY(1,1) NOT NULL,
    [PartyId] BIGINT NOT NULL,
    [DefinitionId] BIGINT NOT NULL,
    [ValueText] NVARCHAR(1000) NULL,
    [ValueEnc] VARBINARY(512) NULL,
    [EncKeyPurpose] VARCHAR(11) NOT NULL CONSTRAINT [DF_PartyCustomField_EncKeyPurpose] DEFAULT 'DATA',
    [EncKeyId] BIGINT NULL,
    [ValueMask] NVARCHAR(32) NULL,
    [CurrencyId] INT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_PartyCustomField_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_PartyCustomField] PRIMARY KEY CLUSTERED ([PartyCustomFieldId]),
    CONSTRAINT [UQ_PartyCustomField_Tenant] UNIQUE ([TenantId], [PartyCustomFieldId]),
    CONSTRAINT [UQ_PartyCustomField_PartyId_DefinitionId] UNIQUE ([TenantId], [PartyId], [DefinitionId]),
    CONSTRAINT [CK_PartyCustomField_1] CHECK (ValueText IS NULL OR ValueEnc IS NULL),
    CONSTRAINT [CK_PartyCustomField_2] CHECK (ValueEnc IS NULL OR ValueMask IS NOT NULL),
    CONSTRAINT [CK_PartyCustomField_3] CHECK (ValueEnc IS NULL OR (EncKeyId IS NOT NULL AND DATALENGTH(ValueEnc) >= 29)),
    CONSTRAINT [CK_PartyCustomField_EncKeyPurpose] CHECK ([EncKeyPurpose] IS NULL OR [EncKeyPurpose] IN ('DATA'))
);
GO
-- KYC completeness checklist per bank and role (FR-PTY-023, BR-PTY-012..013, G-8, G-14)
CREATE TABLE [pty].[KycProfile] (
    [TenantId] INT NOT NULL,
    [KycProfileId] BIGINT IDENTITY(1,1) NOT NULL,
    [InstitutionId] BIGINT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [AppliesToRole] VARCHAR(11) NOT NULL,
    [AppliesToKind] VARCHAR(12) NULL,
    [Version] INT NOT NULL CONSTRAINT [DF_KycProfile_Version] DEFAULT 1,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_KycProfile_Status] DEFAULT 'DRAFT',
    [IsBaseline] BIT NOT NULL CONSTRAINT [DF_KycProfile_IsBaseline] DEFAULT 0,
    [OwnerThresholdPct] DECIMAL(9,6) NULL,
    [SourceDocumentId] BIGINT NULL,
    [SeedKey] VARCHAR(80) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_KycProfile_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_KycProfile_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_KycProfile] PRIMARY KEY CLUSTERED ([KycProfileId]),
    CONSTRAINT [UQ_KycProfile_Tenant] UNIQUE ([TenantId], [KycProfileId]),
    CONSTRAINT [UQ_KycProfile_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_KycProfile_InstitutionId_AppliesToRole_AppliesToKind_Version] UNIQUE ([TenantId], [InstitutionId], [AppliesToRole], [AppliesToKind], [Version]),
    CONSTRAINT [CK_KycProfile_1] CHECK (InstitutionId IS NOT NULL OR IsBaseline = 1),
    CONSTRAINT [CK_KycProfile_2] CHECK (Version >= 1),
    CONSTRAINT [CK_KycProfile_3] CHECK (OwnerThresholdPct IS NULL OR (OwnerThresholdPct > 0 AND OwnerThresholdPct <= 100)),
    CONSTRAINT [CK_KycProfile_AppliesToRole] CHECK ([AppliesToRole] IS NULL OR [AppliesToRole] IN ('GUARANTOR', 'SHAREHOLDER', 'SIGNATORY', 'ANY')),
    CONSTRAINT [CK_KycProfile_AppliesToKind] CHECK ([AppliesToKind] IS NULL OR [AppliesToKind] IN ('INDIVIDUAL', 'ORGANIZATION')),
    CONSTRAINT [CK_KycProfile_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'ACTIVE', 'RETIRED'))
);
GO
-- Completeness item (FR-PTY-023, FR-PTY-024, G-14)
CREATE TABLE [pty].[KycProfileItem] (
    [TenantId] INT NOT NULL,
    [KycProfileItemId] BIGINT IDENTITY(1,1) NOT NULL,
    [ProfileId] BIGINT NOT NULL,
    [ItemKind] VARCHAR(17) NOT NULL,
    [RefCode] VARCHAR(60) NOT NULL,
    [ConditionJson] NVARCHAR(MAX) NULL,
    [IsMandatory] BIT NOT NULL CONSTRAINT [DF_KycProfileItem_IsMandatory] DEFAULT 1,
    [MinValidityDays] INT NULL,
    [MaxAgeDays] INT NULL,
    [RequiresImage] BIT NOT NULL CONSTRAINT [DF_KycProfileItem_RequiresImage] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_KycProfileItem_SortOrder] DEFAULT 0,
    [HelpTextAr] NVARCHAR(500) NULL,
    [HelpTextEn] NVARCHAR(500) NULL,
    [SeedKey] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_KycProfileItem_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_KycProfileItem] PRIMARY KEY CLUSTERED ([KycProfileItemId]),
    CONSTRAINT [UQ_KycProfileItem_Tenant] UNIQUE ([TenantId], [KycProfileItemId]),
    CONSTRAINT [UQ_KycProfileItem_ProfileId_ItemKind_RefCode] UNIQUE ([TenantId], [ProfileId], [ItemKind], [RefCode]),
    CONSTRAINT [CK_KycProfileItem_1] CHECK (MinValidityDays IS NULL OR MinValidityDays >= 0),
    CONSTRAINT [CK_KycProfileItem_2] CHECK (MaxAgeDays IS NULL OR MaxAgeDays > 0),
    CONSTRAINT [CK_KycProfileItem_ItemKind] CHECK ([ItemKind] IS NULL OR [ItemKind] IN ('PARTY_FIELD', 'IDENTITY_DOC', 'DOCUMENT_TYPE', 'ADDRESS_TYPE', 'CONTACT_KIND', 'CUSTOM_FIELD', 'COMPANY_FIELD', 'RELATED_PARTY_SET')),
    CONSTRAINT [CK_KycProfileItem_ConditionJson_json] CHECK ([ConditionJson] IS NULL OR ISJSON([ConditionJson], VALUE) = 1)
);
GO
-- Conditions for an item to apply, by legal form; no rows = applies to all (G-15)
CREATE TABLE [pty].[KycProfileItemLegalForm] (
    [TenantId] INT NOT NULL,
    [KycProfileItemId] BIGINT NOT NULL,
    [LegalEntityTypeId] INT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_KycProfileItemLegalForm_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_KycProfileItemLegalForm] PRIMARY KEY CLUSTERED ([TenantId], [KycProfileItemId], [LegalEntityTypeId])
);
GO
-- Dated compliance declarations per person in their capacity: PEP, sanctions, investigations, immunity (G-9)
CREATE TABLE [pty].[PartyCompliance] (
    [TenantId] INT NOT NULL,
    [PartyComplianceId] BIGINT IDENTITY(1,1) NOT NULL,
    [PartyId] BIGINT NOT NULL,
    [Capacity] VARCHAR(16) NOT NULL,
    [CompanyId] BIGINT NULL,
    [DeclaredOn] DATE NOT NULL,
    [IsCurrent] BIT NOT NULL CONSTRAINT [DF_PartyCompliance_IsCurrent] DEFAULT 1,
    [IsPep] BIT NOT NULL CONSTRAINT [DF_PartyCompliance_IsPep] DEFAULT 0,
    [IsRelatedToPep] BIT NOT NULL CONSTRAINT [DF_PartyCompliance_IsRelatedToPep] DEFAULT 0,
    [IsSanctioned] BIT NOT NULL CONSTRAINT [DF_PartyCompliance_IsSanctioned] DEFAULT 0,
    [IsUnderInvestigation] BIT NOT NULL CONSTRAINT [DF_PartyCompliance_IsUnderInvestigation] DEFAULT 0,
    [HasImmunity] BIT NOT NULL CONSTRAINT [DF_PartyCompliance_HasImmunity] DEFAULT 0,
    [Details] NVARCHAR(MAX) NULL,
    [SourceDocumentId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_PartyCompliance_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_PartyCompliance] PRIMARY KEY CLUSTERED ([PartyComplianceId]),
    CONSTRAINT [UQ_PartyCompliance_Tenant] UNIQUE ([TenantId], [PartyComplianceId]),
    CONSTRAINT [UQ_PartyCompliance_PartyId_Capacity_CompanyId_DeclaredOn] UNIQUE ([TenantId], [PartyId], [Capacity], [CompanyId], [DeclaredOn]),
    CONSTRAINT [CK_PartyCompliance_Capacity] CHECK ([Capacity] IS NULL OR [Capacity] IN ('OWNER', 'BENEFICIAL_OWNER', 'BOARD_MEMBER', 'EXECUTIVE', 'SIGNATORY', 'OTHER'))
);
GO
-- Tax identity and FATCA/CRS tax declaration (G-13)
CREATE TABLE [pty].[TaxIdentity] (
    [TenantId] INT NOT NULL,
    [TaxIdentityId] BIGINT IDENTITY(1,1) NOT NULL,
    [PartyId] BIGINT NOT NULL,
    [CountryId] INT NOT NULL,
    [TaxNumber] VARCHAR(40) NULL,
    [VatNumber] VARCHAR(40) NULL,
    [FatcaClassificationId] INT NULL,
    [CrsClassificationId] INT NULL,
    [DeclarationDate] DATE NOT NULL,
    [IsCurrent] BIT NOT NULL CONSTRAINT [DF_TaxIdentity_IsCurrent] DEFAULT 1,
    [SourceDocumentId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TaxIdentity_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TaxIdentity] PRIMARY KEY CLUSTERED ([TaxIdentityId]),
    CONSTRAINT [UQ_TaxIdentity_Tenant] UNIQUE ([TenantId], [TaxIdentityId]),
    CONSTRAINT [UQ_TaxIdentity_PartyId_CountryId_DeclarationDate] UNIQUE ([TenantId], [PartyId], [CountryId], [DeclarationDate]),
    CONSTRAINT [CK_TaxIdentity_1] CHECK (TaxNumber IS NOT NULL OR VatNumber IS NOT NULL OR FatcaClassificationId IS NOT NULL OR CrsClassificationId IS NOT NULL)
);
GO

-- ===== schema ref =====
-- Country: global reference, read-only, managed by the platform operator (FR-CAT-026, BR-CAT-018, BR-CAT-015)
CREATE TABLE [ref].[Country] (
    [CountryId] INT IDENTITY(1,1) NOT NULL,
    [Iso2] CHAR(2) NOT NULL,
    [Iso3] CHAR(3) NOT NULL,
    [NameAr] NVARCHAR(100) NOT NULL,
    [NameEn] NVARCHAR(100) NOT NULL,
    [IsGcc] BIT NOT NULL CONSTRAINT [DF_Country_IsGcc] DEFAULT 0,
    [WeekendDays] VARCHAR(40) NULL,
    [DialCode] VARCHAR(8) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Country_IsActive] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Country_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_Country] PRIMARY KEY CLUSTERED ([CountryId]),
    CONSTRAINT [UQ_Country_Iso2] UNIQUE ([Iso2]),
    CONSTRAINT [UQ_Country_Iso3] UNIQUE ([Iso3]),
    CONSTRAINT [CK_Country_1] CHECK (Iso2 COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z]%' AND Iso3 COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z]%'),
    CONSTRAINT [CK_Country_2] CHECK (DialCode IS NULL OR (DialCode LIKE '+[0-9]%' AND DialCode NOT LIKE '+%[^0-9]%' AND DialCode NOT LIKE '+_____%')),
    CONSTRAINT [CK_Country_3] CHECK (WeekendDays IS NULL OR WeekendDays COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z,]%'),
    CONSTRAINT [CK_Country_WeekendDays] CHECK ([WeekendDays] IS NULL OR LEN([WeekendDays]) + 1 = CASE WHEN CHARINDEX(',MON,', (',' + [WeekendDays] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 4 ELSE 0 END + CASE WHEN CHARINDEX(',TUE,', (',' + [WeekendDays] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 4 ELSE 0 END + CASE WHEN CHARINDEX(',WED,', (',' + [WeekendDays] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 4 ELSE 0 END + CASE WHEN CHARINDEX(',THU,', (',' + [WeekendDays] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 4 ELSE 0 END + CASE WHEN CHARINDEX(',FRI,', (',' + [WeekendDays] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 4 ELSE 0 END + CASE WHEN CHARINDEX(',SAT,', (',' + [WeekendDays] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 4 ELSE 0 END + CASE WHEN CHARINDEX(',SUN,', (',' + [WeekendDays] + ',') COLLATE Arabic_100_BIN2) > 0 THEN 4 ELSE 0 END)
);
GO
-- Currency: global ISO 4217 reference, read-only (FR-CAT-021, Q-CAT-08)
CREATE TABLE [ref].[Currency] (
    [CurrencyId] INT IDENTITY(1,1) NOT NULL,
    [Code] CHAR(3) NOT NULL,
    [NumericCode] CHAR(3) NOT NULL,
    [NameAr] NVARCHAR(100) NOT NULL,
    [NameEn] NVARCHAR(100) NOT NULL,
    [Decimals] TINYINT NOT NULL,
    [Symbol] NVARCHAR(10) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Currency_IsActive] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Currency_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_Currency] PRIMARY KEY CLUSTERED ([CurrencyId]),
    CONSTRAINT [UQ_Currency_Code] UNIQUE ([Code]),
    CONSTRAINT [UQ_Currency_NumericCode] UNIQUE ([NumericCode]),
    CONSTRAINT [CK_Currency_1] CHECK (Decimals BETWEEN 0 AND 3),
    CONSTRAINT [CK_Currency_2] CHECK (Code COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z]%'),
    CONSTRAINT [CK_Currency_3] CHECK (NumericCode NOT LIKE '%[^0-9]%')
);
GO
-- An economic activity of the Saudi classification of economic activities (GASTAT, ISIC Rev.4): section and division; a company's main activity (docs/35 section 5)
CREATE TABLE [ref].[Industry] (
    [IndustryId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(10) NOT NULL,
    [SectionCode] CHAR(1) NOT NULL,
    [ParentId] INT NULL,
    [NameAr] NVARCHAR(300) NOT NULL,
    [NameEn] NVARCHAR(300) NOT NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Industry_IsActive] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Industry_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_Industry] PRIMARY KEY CLUSTERED ([IndustryId]),
    CONSTRAINT [UQ_Industry_Code] UNIQUE ([Code]),
    CONSTRAINT [CK_Industry_1] CHECK (SectionCode COLLATE Arabic_100_BIN2 LIKE '[A-U]'),
    CONSTRAINT [CK_Industry_2] CHECK (Code COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z0-9]%')
);
GO
-- Incoterms delivery term: global reference, read-only, managed by the operator; legacy terms are displayed, not selectable (FR-LCT-013, FR-CAT-021, BR-CAT-015)
CREATE TABLE [ref].[Incoterm] (
    [IncotermId] INT IDENTITY(1,1) NOT NULL,
    [Code] CHAR(3) NOT NULL,
    [NameEn] NVARCHAR(100) NOT NULL,
    [NameAr] NVARCHAR(100) NULL,
    [RulesVersion] VARCHAR(10) NOT NULL CONSTRAINT [DF_Incoterm_RulesVersion] DEFAULT '2020',
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_Incoterm_Status] DEFAULT 'ACTIVE',
    [IsSeaOnly] BIT NOT NULL CONSTRAINT [DF_Incoterm_IsSeaOnly] DEFAULT 0,
    [RequiresInsurance] BIT NOT NULL CONSTRAINT [DF_Incoterm_RequiresInsurance] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_Incoterm_SortOrder] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Incoterm_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_Incoterm] PRIMARY KEY CLUSTERED ([IncotermId]),
    CONSTRAINT [UQ_Incoterm_Code] UNIQUE ([Code]),
    CONSTRAINT [CK_Incoterm_1] CHECK (Code COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z]%'),
    CONSTRAINT [CK_Incoterm_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'LEGACY'))
);
GO
-- UCP 600 reference article: NULL TenantId = global read-only row, published only by the platform operator (FR-LCT-006, BR-LCT-018, BR-PLT-001)
CREATE TABLE [ref].[UcpArticle] (
    [TenantId] INT NULL,
    [UcpArticleId] INT IDENTITY(1,1) NOT NULL,
    [Version] VARCHAR(10) NOT NULL CONSTRAINT [DF_UcpArticle_Version] DEFAULT 'UCP600',
    [ArticleNo] VARCHAR(10) NOT NULL,
    [TitleAr] NVARCHAR(300) NOT NULL,
    [TitleEn] NVARCHAR(300) NOT NULL,
    [TopicAr] NVARCHAR(200) NULL,
    [VerificationStatus] VARCHAR(10) NOT NULL CONSTRAINT [DF_UcpArticle_VerificationStatus] DEFAULT 'UNVERIFIED',
    [VerifiedBy] INT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [VerifierNote] NVARCHAR(MAX) NULL,
    [SeedKey] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UcpArticle_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_UcpArticle] PRIMARY KEY CLUSTERED ([UcpArticleId]),
    CONSTRAINT [UQ_UcpArticle_Tenant] UNIQUE ([TenantId], [UcpArticleId]),
    CONSTRAINT [UQ_UcpArticle_Version_ArticleNo] UNIQUE ([TenantId], [Version], [ArticleNo]),
    CONSTRAINT [CK_UcpArticle_1] CHECK (VerificationStatus <> 'VERIFIED' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_UcpArticle_2] CHECK (VerificationStatus = 'VERIFIED' OR (VerifiedBy IS NULL AND VerifiedOn IS NULL)),
    CONSTRAINT [CK_UcpArticle_VerificationStatus] CHECK ([VerificationStatus] IS NULL OR [VerificationStatus] IN ('UNVERIFIED', 'VERIFIED'))
);
GO

