    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_ProductCategory_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_ProductCategory_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_ProductCategory_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_ProductCategory_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ProductCategory_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ProductCategory] PRIMARY KEY CLUSTERED ([ProductCategoryId]),
    CONSTRAINT [UQ_ProductCategory_Tenant] UNIQUE ([TenantId], [ProductCategoryId]),
    CONSTRAINT [UQ_ProductCategory_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_ProductCategory_1] CHECK (Code COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z0-9_]%' AND Code NOT LIKE '[0-9_]%'),
    CONSTRAINT [CK_ProductCategory_2] CHECK ((IsLocked = 0 OR (IsSystem = 1 AND IsActive = 1)) AND (IsSystem = 0 OR NameEn IS NOT NULL))
);
GO
-- Bank product with its flags (FR-CAT-007, BR-CAT-004)
CREATE TABLE [cat].[Product] (
    [TenantId] INT NOT NULL,
    [ProductId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Product_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_Product_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_Product_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_Product_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [ProductCategoryId] INT NOT NULL,
    [ProductFamily] VARCHAR(15) NOT NULL,
    [ConsumesCreditLimit] BIT NOT NULL,
    [IsTradeFinance] BIT NOT NULL CONSTRAINT [DF_Product_IsTradeFinance] DEFAULT 0,
    [Compliance] VARCHAR(12) NOT NULL,
    [VariantGroupCode] VARCHAR(40) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Product_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Product] PRIMARY KEY CLUSTERED ([ProductId]),
    CONSTRAINT [UQ_Product_Tenant] UNIQUE ([TenantId], [ProductId]),
    CONSTRAINT [UQ_Product_Scope_Compliance] UNIQUE ([TenantId], [Compliance], [ProductId]),
    CONSTRAINT [UQ_Product_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_Product_1] CHECK (Code COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z0-9_]%' AND Code NOT LIKE '[0-9_]%'),
    CONSTRAINT [CK_Product_2] CHECK ((IsLocked = 0 OR (IsSystem = 1 AND IsActive = 1)) AND (IsSystem = 0 OR NameEn IS NOT NULL)),
    CONSTRAINT [CK_Product_ProductFamily] CHECK ([ProductFamily] IS NULL OR [ProductFamily] IN ('LC', 'GUARANTEE', 'FINANCING', 'COLLECTION', 'FX', 'PAYMENT', 'CARD', 'ACCOUNT_SERVICE', 'OTHER')),
    CONSTRAINT [CK_Product_Compliance] CHECK ([Compliance] IS NULL OR [Compliance] IN ('CONVENTIONAL', 'ISLAMIC', 'NEUTRAL'))
);
