-- Limit type: master or sub-limit (FR-CAT-012, BR-CAT-008)
CREATE TABLE [cat].[LimitType] (
    [TenantId] INT NOT NULL,
    [LimitTypeId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_LimitType_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_LimitType_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_LimitType_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_LimitType_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [Kind] VARCHAR(10) NOT NULL,
    [ParentLimitTypeId] INT NULL,
    [DefaultDistributionMode] VARCHAR(13) NULL,
    [DefaultIsRevolving] BIT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LimitType_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LimitType] PRIMARY KEY CLUSTERED ([LimitTypeId]),
    CONSTRAINT [UQ_LimitType_Tenant] UNIQUE ([TenantId], [LimitTypeId]),
    CONSTRAINT [UQ_LimitType_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_LimitType_1] CHECK ((Kind = 'MAIN' AND ParentLimitTypeId IS NULL) OR (Kind = 'SUB' AND ParentLimitTypeId IS NOT NULL)),
    CONSTRAINT [CK_LimitType_2] CHECK (ParentLimitTypeId IS NULL OR ParentLimitTypeId <> LimitTypeId),
    CONSTRAINT [CK_LimitType_3] CHECK (Code COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z0-9_]%' AND Code NOT LIKE '[0-9_]%'),
    CONSTRAINT [CK_LimitType_4] CHECK ((IsLocked = 0 OR (IsSystem = 1 AND IsActive = 1)) AND (IsSystem = 0 OR NameEn IS NOT NULL)),
    CONSTRAINT [CK_LimitType_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('MAIN', 'SUB')),
    CONSTRAINT [CK_LimitType_DefaultDistributionMode] CHECK ([DefaultDistributionMode] IS NULL OR [DefaultDistributionMode] IN ('SHARED_CAP', 'PARTITION', 'OUTSIDE_TOTAL'))
);
