    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_LimitTypeProduct] PRIMARY KEY CLUSTERED ([TenantId], [LimitTypeId], [ProductId])
);
