-- Collateral type with its structure type and attribute template (FR-CAT-013)
CREATE TABLE [cat].[CollateralType] (
    [TenantId] INT NOT NULL,
    [CollateralTypeId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_CollateralType_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_CollateralType_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_CollateralType_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_CollateralType_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [StructureKind] VARCHAR(20) NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CollateralType_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CollateralType] PRIMARY KEY CLUSTERED ([CollateralTypeId]),
    CONSTRAINT [UQ_CollateralType_Tenant] UNIQUE ([TenantId], [CollateralTypeId]),
    CONSTRAINT [UQ_CollateralType_Scope_StructureKind] UNIQUE ([TenantId], [StructureKind], [CollateralTypeId]),
    CONSTRAINT [UQ_CollateralType_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_CollateralType_1] CHECK (Code COLLATE Arabic_100_BIN2 NOT LIKE '%[^A-Z0-9_]%' AND Code NOT LIKE '[0-9_]%'),
    CONSTRAINT [CK_CollateralType_2] CHECK ((IsLocked = 0 OR (IsSystem = 1 AND IsActive = 1)) AND (IsSystem = 0 OR NameEn IS NOT NULL)),
    CONSTRAINT [CK_CollateralType_StructureKind] CHECK ([StructureKind] IS NULL OR [StructureKind] IN ('GUARANTEE', 'PROMISSORY_NOTE', 'INSURANCE_ASSIGNMENT', 'CASH_MARGIN', 'REAL_ESTATE', 'SET_OFF', 'NEGATIVE_PLEDGE', 'GENERIC'))
);
GO
-- Attribute in a collateral-type template; never deleted, only marked Retired (BR-CAT-009) -- جدول جديد
CREATE TABLE [cat].[CollateralTypeAttribute] (
    [TenantId] INT NOT NULL,
    [CollateralTypeAttributeId] INT IDENTITY(1,1) NOT NULL,
    [CollateralTypeId] INT NOT NULL,
    [AttrKey] VARCHAR(60) NOT NULL,
    [LabelAr] NVARCHAR(200) NOT NULL,
    [LabelEn] NVARCHAR(200) NOT NULL,
    [DataType] VARCHAR(10) NOT NULL,
    [IsRequired] BIT NOT NULL CONSTRAINT [DF_CollateralTypeAttribute_IsRequired] DEFAULT 0,
    [ListOptions] NVARCHAR(MAX) NULL,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_CollateralTypeAttribute_SortOrder] DEFAULT 0,
    [IsRetired] BIT NOT NULL CONSTRAINT [DF_CollateralTypeAttribute_IsRetired] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CollateralTypeAttribute_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CollateralTypeAttribute] PRIMARY KEY CLUSTERED ([CollateralTypeAttributeId]),
    CONSTRAINT [UQ_CollateralTypeAttribute_Tenant] UNIQUE ([TenantId], [CollateralTypeAttributeId]),
    CONSTRAINT [UQ_CollateralTypeAttribute_CollateralTypeId_AttrKey] UNIQUE ([TenantId], [CollateralTypeId], [AttrKey]),
    CONSTRAINT [CK_CollateralTypeAttribute_1] CHECK (DataType <> 'LIST' OR ListOptions IS NOT NULL),
    CONSTRAINT [CK_CollateralTypeAttribute_DataType] CHECK ([DataType] IS NULL OR [DataType] IN ('TEXT', 'NUMBER', 'DATE', 'AMOUNT', 'BOOLEAN', 'LIST', 'REFERENCE')),
    CONSTRAINT [CK_CollateralTypeAttribute_ListOptions_json] CHECK ([ListOptions] IS NULL OR ISJSON([ListOptions], VALUE) = 1)
);
