    [FacilityId] BIGINT NOT NULL,
    [LimitProductLineId] BIGINT NOT NULL,
    [MaxTotalTenorDays] INT NULL,
    [MaxDeferralDays] INT NULL,
    [MaxPostDeferralFinancingDays] INT NULL,
    [LcValidityDays] INT NULL,
