    [InheritedRootId] BIGINT NULL,
    [RootId] AS (CASE WHEN InheritedRootId IS NULL THEN ProductLineTermId ELSE InheritedRootId END) PERSISTED,
    [SourceDocumentId] BIGINT NULL,
