    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_ProductLineTerm_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_ProductLineTerm_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ProductLineTerm_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ProductLineTerm] PRIMARY KEY CLUSTERED ([ProductLineTermId]),
    CONSTRAINT [UQ_ProductLineTerm_Tenant] UNIQUE ([TenantId], [ProductLineTermId]),
    CONSTRAINT [UQ_ProductLineTerm_Scope_RootId] UNIQUE ([TenantId], [RootId], [ProductLineTermId]),
    CONSTRAINT [CK_ProductLineTerm_1] CHECK (EffectiveTo IS NULL OR EffectiveTo >= EffectiveFrom),
    CONSTRAINT [CK_ProductLineTerm_2] CHECK (MaxTotalTenorDays IS NULL OR MaxTotalTenorDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_3] CHECK (MaxDeferralDays IS NULL OR MaxDeferralDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_4] CHECK (MaxPostDeferralFinancingDays IS NULL OR MaxPostDeferralFinancingDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_5] CHECK (LcValidityDays IS NULL OR LcValidityDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_6] CHECK (AdvanceNoticeDays IS NULL OR AdvanceNoticeDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_7] CHECK (CashCoverPct IS NULL OR (CashCoverPct >= 0 AND CashCoverPct <= 100)),
    CONSTRAINT [CK_ProductLineTerm_8] CHECK (FinancingRatioPct IS NULL OR (FinancingRatioPct >= 0 AND FinancingRatioPct <= 100)),
    CONSTRAINT [CK_ProductLineTerm_9] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_ProductLineTerm_10] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_ProductLineTerm_11] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_ProductLineTerm_12] CHECK ((SupersedesId IS NULL AND InheritedRootId IS NULL) OR (SupersedesId IS NOT NULL AND InheritedRootId IS NOT NULL)),
    CONSTRAINT [CK_ProductLineTerm_13] CHECK (OriginalText IS NULL OR (OriginalText COLLATE Arabic_100_BIN2 NOT LIKE '%[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]%' AND OriginalText COLLATE Arabic_100_BIN2 NOT LIKE '%[A-Za-z][A-Za-z][0-9][0-9] [0-9][0-9][0-9][0-9] [0-9][0-9][0-9][0-9] [0-9][0-9][0-9][0-9]%')),
    CONSTRAINT [CK_ProductLineTerm_14] CHECK (SourceDocumentId IS NOT NULL OR (NoSourceReason IS NOT NULL AND LEN(LTRIM(RTRIM(NoSourceReason))) > 0)),
    CONSTRAINT [CK_ProductLineTerm_AdvanceNoticeUnit] CHECK ([AdvanceNoticeUnit] IS NULL OR [AdvanceNoticeUnit] IN ('BUSINESS', 'CALENDAR')),
    CONSTRAINT [CK_ProductLineTerm_CheckMode] CHECK ([CheckMode] IS NULL OR [CheckMode] IN ('OFF', 'WARN', 'BLOCK')),
    CONSTRAINT [CK_ProductLineTerm_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
